INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (2443, NULL, 'PERSON', 0, 'People, kinship, social roles, human identity and relationships');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (2444, NULL, 'BODY', 0, 'Body parts, physical states, health, bodily functions');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (2445, NULL, 'LOCATION', 0, 'Places, geographical features, spatial relations, directions');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (2446, NULL, 'ARTIFACT', 0, 'Man-made objects, tools, buildings, vessels, materials');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (2447, NULL, 'FOOD_DRINK', 0, 'Food, drink, cooking, eating, agricultural produce for consumption');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (2448, NULL, 'ANIMAL', 0, 'Animals, livestock, wild creatures, insects, animal products');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (2449, NULL, 'PLANT', 0, 'Plants, trees, agriculture, vegetation, botanical terms');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (2450, NULL, 'NATURAL_WORLD', 0, 'Weather, celestial bodies, elements, natural phenomena, seasons');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (2451, NULL, 'TIME', 0, 'Time periods, seasons, ages, temporal references, duration');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (2452, NULL, 'EVENT', 0, 'Events, happenings, occurrences, festivals, ceremonies');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (2453, NULL, 'ACTION', 0, 'Physical actions, motion, work, making, breaking, giving');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (2454, NULL, 'SPEECH', 0, 'Speaking, communication, language, writing, messages, oaths');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (2455, NULL, 'COGNITION', 0, 'Thinking, knowing, learning, understanding, wisdom, memory');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (2456, NULL, 'EMOTION', 0, 'Feelings, emotions, desires, attitudes, psychological states');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (2457, NULL, 'MORAL', 0, 'Righteousness, sin, purity, guilt, ethical concepts, virtue/vice');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (2458, NULL, 'SOCIAL', 0, 'Social interactions, community, customs, law, justice, trade');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (2459, NULL, 'AUTHORITY', 0, 'Power, rulership, government, military, servitude, command');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (2460, NULL, 'WORSHIP', 0, 'Worship, sacrifice, prayer, temple, priesthood, religious practice');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (2461, NULL, 'SUPERNATURAL', 0, 'God, divine beings, angels, demons, spiritual reality, prophecy');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (2462, NULL, 'QUANTITY', 0, 'Numbers, measurement, size, weight, distance, abundance/lack');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4587, 2444, 'Comparative Measurement', 1, 'This domain encompasses words and constructions used to express comparison, superiority, excess, or relative quantity between entities, typically expressed in English as "more than," "greater than," or "beyond."');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4588, 2444, 'Spatial Relations and Extent', 1, 'Words expressing spatial relationships, surfaces, locations, and boundaries between entities, including concepts of proximity, direction, position above/upon/over, and physical extent or measurement.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4589, 2451, 'Degree and Intensity', 1, 'This domain encompasses adverbs and adjectives expressing high degrees of quantity, magnitude, or intensity, including words meaning "very," "greatly," "much," "many," "exceedingly," and "abundant."');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4590, 2457, 'Transactions and Obligations', 1, 'This domain encompasses actions involving the transfer, exchange, or management of persons, property, and obligations, including sending, releasing, lending, pledging, cursing, recognizing, and valuing.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4591, 2454, 'Sustain and Rescue', 1, 'This domain encompasses actions of providing support, sustenance, or deliverance to persons in need, including physical nourishment, upholding in difficult circumstances, and rescue from danger or oppression.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4592, 2455, 'Affirmation and Identification', 1, 'Words expressing emphatic agreement, confirmation, identification, or demonstrative reference to previously mentioned entities or states of being.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4593, 2449, 'Goodness and Well-being', 1, 'This domain encompasses words expressing moral and material goodness, welfare, beauty, and actions that promote well-being or are done skillfully and rightly.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4594, 2455, 'Expulsion and Departure', 1, 'This domain encompasses words related to forcibly removing, driving out, or expelling people from a place, as well as voluntarily departing or exiting from locations, with emphasis on the physical movement outward from an origin point.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4595, 2451, 'Temporal Causation and Sequence', 1, 'Words that express temporal relationships (when, after, since) and causal connections (because, inasmuch as) between events, often introducing subordinate clauses that explain timing or reasons.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4596, 2452, 'Negative Events and Outcomes', 1, 'This domain encompasses expressions of negation, destruction, corruption, and the absence or prevention of events, including particles of negation, verbs of ruining or spoiling, and constructions indicating non-occurrence or impossibility.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4597, 2453, 'Contrastive and Emphatic Assertion', 1, 'Words and particles that express contrast, limitation, emphasis, or strong affirmation, often used to contradict, restrict, or intensify a preceding statement.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4598, 2452, 'Interrogative Speech Acts', 1, 'This domain encompasses interrogative words and constructions used to elicit information, including questions about identity (what, which), quality (what kind), purpose (why, for what), time (when, since), and manner (how), as well as comparative and causal constructions in speech.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4599, 2455, 'Receiving and Welcoming', 1, 'This domain encompasses cognitive and social acts of accepting, admitting, or welcoming someone or something into one''s presence, home, group, or care, including the mental acknowledgment or acceptance involved in receiving.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4600, 2454, 'Divine Power and Manifestation', 1, 'Words referring to supernatural power, divine strength, miraculous works, and the manifestation of God''s ability through extraordinary deeds or cosmic forces.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4601, 2457, 'Forceful Actions Against Others', 1, 'Words describing actions of physical force, violence, or punishment inflicted upon people or things, including binding, breaking, scattering, afflicting, burying, and striking.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4602, 2443, 'Textual Variants and Marginal Readings', 1, 'Words and forms that represent alternative manuscript readings, scribal notations, archaic forms, or textual variants that appear in the critical apparatus rather than representing a unified semantic concept.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4603, 2444, 'Strength and Power', 1, 'This domain encompasses words describing physical strength, might, courage, and the ability to prevail or overcome, whether referring to persons, armies, God, or abstract qualities like authority and resolve.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4604, 2460, 'Ritual Food and Eating', 1, 'This domain encompasses words related to food, eating, and edibility in the context of religious dietary laws, sacrificial meals, and ritual purity distinctions regarding what may or may not be consumed.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4605, 2461, 'Destruction and Ruin', 1, 'This domain encompasses terms for places, states, or personifications of utter destruction, corruption, and ruin, particularly associated with death, the underworld, or complete desolation.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4606, 2462, 'Sacred and Holy', 1, 'This domain encompasses words and concepts related to holiness, sacredness, consecration, and being set apart for divine purposes, including holy persons, places, objects, and the act of sanctifying or hallowing.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4607, 2458, 'Downfall and Destruction', 1, 'Words describing persons or entities being brought down, overthrown, demolished, or destroyed, whether through physical descent, defeat, ruin, or death.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4608, 2444, 'Lift Up, Raise High', 1, 'This domain encompasses actions and states of physically lifting, raising, or elevating objects or body parts, as well as metaphorical uses of elevation including exaltation of status, honor, or divine majesty.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4609, 2447, 'Evil and Wickedness', 1, 'This domain encompasses terms describing moral wrongdoing, wickedness, calamity, harmful actions, and negative emotional or physical states, ranging from ethical evil and malicious intent to adversity, disaster, and suffering.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4610, 2446, 'Enumeration and Distribution', 1, 'Words expressing numerical quantity, distributive relationships, and indefinite reference, particularly focusing on the concept of "one" in its cardinal, ordinal, distributive, and indefinite article functions.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4611, 2458, 'Command and Authority', 1, 'Words referring to giving orders, commands, or instructions to others, typically from a position of authority.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4612, 2460, 'Passing and Transition', 1, 'Words describing movement across spaces or boundaries, temporal progression, and the cessation or ending of states, objects, or time periods.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4613, 2449, 'Future Time and Coming Events', 1, 'This domain contains words and expressions related to things that will happen, arrive, or come to pass in the future, including temporal references to upcoming events, expectations, and arrivals.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4614, 2450, 'Joy and Gladness', 1, 'Abstract emotional states and expressions of happiness, rejoicing, exultation, cheerfulness, and delight, often in response to favorable circumstances or divine blessing.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4615, 2458, 'Gathering and Assembly', 1, 'This domain encompasses actions related to bringing people, objects, or substances together in one place, including assembling groups, collecting items, harvesting crops, and the end-of-life gathering to one''s ancestors.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4616, 2452, 'Conditional and Contrastive Markers', 1, 'This domain contains particles and conjunctions that introduce conditions (if, whether), alternatives (or), contrasts (but, rather), and related discourse functions including rhetorical questions and emphatic assertions.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4617, 2453, 'Gratuitous Action', 1, 'This domain encompasses actions or states performed without payment, compensation, cause, or purpose—including doing things freely, without cost, without justification, or in vain.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4618, 2454, 'Destruction and Ruin', 1, 'This domain encompasses words related to the complete destruction, corruption, or annihilation of physical objects, people, cities, moral order, or abstract concepts, whether through violent action, gradual decay, or divine judgment.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4619, 2455, 'Raising Up and Elevation', 1, 'This domain encompasses actions of lifting, raising up, bringing up, or causing something or someone to ascend from a lower to a higher position, whether physically, spatially, or metaphorically (such as raising up a leader or establishing something).');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4620, 2456, 'Burning with Passion', 1, 'This domain encompasses words describing intense emotional states, particularly burning desire or passion, using metaphors of fire, heat, and inflammation to express strong feelings like lust, longing, or emotional fervor.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4621, 2457, 'Gift and Offering', 1, 'This domain encompasses voluntary giving, including gifts between people, tribute to rulers, and religious offerings or sacrifices presented to God, emphasizing the generous and willing nature of the presentation.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4622, 2458, 'Fortune and Luck', 1, 'This domain includes words related to fortune, good luck, fate, and deities or forces associated with prosperity and chance outcomes in social life.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4623, 2459, 'Fullness and Completion', 1, 'This domain encompasses words describing states of being full, complete, or filled to capacity, including physical fullness, fulfillment of time periods, and completeness of measure or authority.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4624, 2458, 'Divine Summons and Invitation', 1, 'Words relating to calling, summoning, or inviting people to gatherings, events, or spiritual purposes, including both human invitations and divine calling to salvation or service.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4625, 2461, 'Divine Spirit Descent', 1, 'Words describing supernatural manifestations where the Holy Spirit, divine power, or spiritual influence descends upon or falls upon people, often in the context of prophecy, spiritual gifts, or religious experience.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4626, 2454, 'Outer Garments and Robes', 1, 'This domain includes words for formal or outer garments worn over other clothing, such as cloaks, robes, mantles, and wraps, typically distinguished from undergarments or tunics.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4627, 2451, 'Death and Execution', 1, 'This domain encompasses words related to death as an event, state, or penalty, including natural death, violent death, capital punishment, and death personified as a power or realm.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4628, 2444, 'Concealment and Hiding', 1, 'This domain encompasses actions and states related to deliberately hiding, concealing, or keeping things secret, whether reflexively (hiding oneself) or transitively (hiding something from others), including both physical concealment and the withholding of information or attention.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4629, 2445, 'Completion and Fulfillment', 1, 'This domain encompasses words describing the state of being complete, whole, or perfect, as well as actions that bring something to completion, accomplish goals, fulfill promises or prophecies, or reach the end of a process or time period.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4630, 2446, 'Seizing and Grasping', 1, 'Words referring to physically taking hold of, grabbing, catching, or seizing something or someone with the hands or by force.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4631, 2447, 'Moral Evil and Wrongdoing', 1, 'This domain encompasses words denoting sin, iniquity, wickedness, and moral wrongdoing, including both the acts themselves and their consequences or punishment.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4632, 2448, 'Darkness and Gloom', 1, 'Words referring to darkness, gloom, and obscurity, whether literal (absence of light, night, shadows) or metaphorical (death, the underworld, ignorance, calamity, secrecy).');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4633, 2455, 'Dryness and Aridity', 1, 'This domain encompasses words related to the state of being dry, parched, or withered, including dry land, the process of drying up or withering (of plants, water, body parts), and the causation of dryness.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4634, 2450, 'Thoughts and Mental Activity', 1, 'This domain encompasses words referring to internal cognitive processes, including thoughts, ideas, reasoning, mental plans, purposes, and reflections that occur in the mind.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4635, 2451, 'Turning and Changing Direction', 1, 'Words describing physical or metaphorical turning, changing direction, returning to a previous state or location, or deviating from a path.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4636, 2452, 'Glory and Majesty', 1, 'This domain encompasses words describing visible splendor, honor, magnificence, and exalted dignity, whether referring to wealth, beauty, divine presence, royal status, or reputation.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4637, 2453, 'Temporal and Spatial Extent', 1, 'Words expressing limits or boundaries in time or space, including temporal duration ("until," "while"), spatial extent ("as far as"), and abstract concepts of perpetuity or eternity.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4638, 2458, 'Trembling in Fear', 1, 'This domain encompasses physical and emotional responses of trembling, quaking, shaking, and writhing that occur as expressions of fear, dread, anguish, or reverent awe before God or in response to threatening circumstances.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4639, 2444, 'Wilderness and Desolation', 1, 'This domain encompasses words describing uninhabited, barren, or empty places and states, including physical wilderness areas, desert lands, and conditions of abandonment, isolation, or being devoid of people or resources.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4640, 2448, 'Existence and Being', 1, 'Words and expressions that assert, question, or emphasize the existence, presence, or identity of entities, particularly including copular constructions with pronouns and existential particles.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4641, 2457, 'Physical Violence and Striking', 1, 'This domain encompasses words related to physically hitting, striking, beating, or attacking someone or something, including fatal blows, judicial punishment, military defeat, and divine judgment.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4642, 2458, 'Throwing and Casting Actions', 1, 'This domain encompasses actions of throwing, casting, hurling, or forcefully propelling objects or persons, including both literal physical actions (throwing stones, casting lots, jettisoning cargo) and metaphorical uses (casting away, rejecting, expelling).');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4643, 2459, 'Freedom and Liberty', 1, 'This domain encompasses words describing the state of being free from slavery, oppression, legal obligations, or external control, including both social status (free persons vs. slaves) and the condition of independence or liberation.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4644, 2460, 'Worship Movement', 1, 'This domain encompasses verbs of motion and departure used in the context of worship, religious pilgrimage, and approaching or leaving sacred spaces, including both literal journeying to places of worship and metaphorical spiritual movement.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4645, 2461, 'Captivity and Imprisonment', 1, 'Terms related to physical confinement, including bonds, prisons, guards, and royal escorts who served dual roles as guards and messengers.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4646, 2462, 'Foolishness and Naivety', 1, 'This domain encompasses words describing people who lack wisdom, understanding, or prudence, ranging from innocent simplicity and naivety to senseless foolishness and stupidity.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4647, 2443, 'Thorns and Briars', 1, 'Plants with sharp spines or prickly features, including thornbushes, briers, brambles, and similar vegetation that causes pain or serves as barriers.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4648, 2444, 'Locative proximity adverbs', 1, 'Adverbs indicating spatial deixis or proximity to the speaker or reference point, expressing location or direction toward a nearby place ("here," "hither," "from here").');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4649, 2445, 'Strengthening and Prevailing', 1, 'This domain covers actions of making strong, fortifying, repairing, encouraging others, and prevailing or overcoming in various contexts, including physical strength, moral courage, building repair, and spiritual perseverance.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4650, 2444, 'Anger and Wrath', 1, 'This domain contains words referring to intense emotional responses of anger, fury, indignation, and wrath, particularly as expressions of displeasure or judgment by God or humans.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4651, 2447, 'Rest and Tranquility', 1, 'This domain encompasses concepts of physical rest, cessation from labor, peaceful repose, quiet, and the state of being at ease or undisturbed, including religious observance of rest periods like the Sabbath.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4652, 2448, 'Sheep and Lambs', 1, 'This domain contains words referring to sheep, lambs, and small livestock (particularly sheep and goats), whether as individual animals, flocks, or used literally and metaphorically.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4653, 2449, 'Servants and Slaves', 1, 'Words referring to people who are bound to serve others, either through forced servitude (slavery) or voluntary service, including household servants, subjects of rulers, and those devoted to religious service.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4654, 2450, 'Vision and Perception', 1, 'Words referring to the act of seeing, looking at, observing, or visually perceiving something with the eyes, including both physical sight and visionary experiences.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4655, 2458, 'Speed and Swiftness', 1, 'This domain contains words describing rapid motion, quick action, immediacy in time, or lightness that enables speed.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4656, 2452, 'Covenant Making Events', 1, 'Events involving the formal establishment, cutting, or making of covenants, agreements, pacts, or treaties between parties.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4657, 2453, 'Dwell and Remain', 1, 'This domain encompasses actions of dwelling, residing, staying, or remaining in a place, including both temporary lodging and permanent habitation, as well as persistence in a state or condition.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4658, 2454, 'Human Frailty and Mortality', 1, 'Words referring to humans in their weakness, mortality, and vulnerability, especially in contrast to divine strength or permanence, often emphasizing the transient, fallible, or diseased nature of human existence.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4659, 2455, 'Immaturity and Youth', 1, 'This domain encompasses terms related to young age, inexperience, and childlike qualities in both humans and animals, including literal children, offspring, young animals, and metaphorical descriptions of immature or foolish behavior.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4660, 2456, 'Emotional Burden and Bearing', 1, 'This domain encompasses words related to carrying, bearing, or enduring emotional weight, including lifting up in prayer, bearing guilt or shame, enduring suffering, and the metaphorical carrying of burdens that affect one''s emotional or spiritual state.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4661, 2457, 'Toil and Hardship', 1, 'This domain encompasses words referring to strenuous labor, exertion, suffering, trouble, and the pain or weariness that results from hard work or difficult circumstances.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4662, 2458, 'Joy and Celebration', 1, 'This domain encompasses words expressing intense joy, gladness, rejoicing, and celebratory emotions, typically in response to positive circumstances or as expressions of well-being.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4663, 2459, 'Land Ownership and Property', 1, 'This domain encompasses words referring to fields, plots of land, estates, and landed property as possessions or territories under someone''s control or jurisdiction.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4664, 2460, 'Foreigners and Aliens', 1, 'Words referring to people who are not native members of a community, including temporary residents, immigrants, strangers, and those from other nations or ethnic groups.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4665, 2458, 'Divine Crushing and Breaking', 1, 'Words describing supernatural or divinely-enacted breaking, shattering, crushing, or destruction, often used metaphorically for God''s judgment, deliverance, or breaking of spiritual/emotional states like hearts and pride.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4666, 2462, 'Seeking and Searching', 1, 'This domain encompasses actions of seeking, searching for, investigating, examining, or inquiring after something or someone, including both physical searches and requests for information or spiritual seeking.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4667, 2443, 'Shame and Reproach', 1, 'Words referring to the state of being dishonored, disgraced, or publicly humiliated, including insults, taunts, and the condition of bearing shame or contempt from others.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4668, 2453, 'Time and Temporal Periods', 1, 'Words denoting spans of time, specific moments, seasons, and appointed or appropriate times for events and actions.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4669, 2445, 'Expectation and Waiting', 1, 'This domain encompasses words related to anticipating, expecting, or waiting for someone or something to arrive, happen, or be received, often with a sense of patient anticipation or hopeful expectation in a particular location or context.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4670, 2446, 'Age and Seniority', 1, 'This domain encompasses terms related to being old in years, aging, and aged persons, including both descriptive terms for advanced age and social roles of elders who hold authority in a community.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4671, 2445, 'Silence and Quietness', 1, 'Words relating to being silent, keeping quiet, ceasing from speech or noise, and maintaining stillness or rest.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4672, 2458, 'Interrogative Location Adverbs', 1, 'Words and phrases that ask questions about location, origin, or direction, including "where," "whence" (from where), and related interrogative expressions used to inquire about spatial position or source.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4673, 2449, 'Opening and Revealing', 1, 'Words related to the act of opening physical objects (doors, gates, eyes, mouths) or revealing and making accessible what was previously closed, hidden, or inaccessible.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4674, 2450, 'Power and Rule', 1, 'Words related to exercising authority, dominion, or control over people, territories, or things, including governing, ruling, reigning, and having mastery.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4675, 2451, 'Short Duration and Youth', 1, 'This domain encompasses words describing limited temporal extent (short periods of time) and related concepts of youth, smallness, and insignificance, reflecting the metaphorical connection between brief time spans and the early stages of life or lesser importance.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4676, 2452, 'Fine Linen Materials', 1, 'This domain encompasses fine textile materials, particularly linen, byssus, and cotton fabrics, including their raw forms (flax plant, threads) and finished products (garments, cloth, bandages, nets, and decorative hangings), with special emphasis on high-quality Egyptian linen used in religious and royal contexts.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4677, 2446, 'Physical Placement and Action', 1, 'This domain encompasses actions of physically placing, setting, or positioning objects, people, or body parts in specific locations, as well as related actions of laying hands on, attacking, or inflicting something upon someone.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4678, 2446, 'Transfer of Objects and Authority', 1, 'This domain encompasses verbs related to transferring physical objects, authority, responsibility, or abstract concepts from one entity to another, including giving, bestowing, placing, appointing, and delivering.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4679, 2454, 'Storm and Tempest', 1, 'This domain encompasses words describing violent weather phenomena, particularly storms, tempests, and storm-winds, including both literal meteorological events and figurative uses representing divine wrath, rage, or tumultuous action.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4680, 2445, 'Mourning and Lamentation', 1, 'Words relating to the expression of grief, sorrow, and bereavement through wailing, lamenting, or formal mourning practices, especially in response to death or calamity.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4681, 2462, 'Profit and Gain', 1, 'This domain encompasses words relating to material advantage, financial profit, economic benefit, and gain obtained through work, trade, or other means, often with moral implications regarding whether such profit is justly or unjustly obtained.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4682, 2458, 'Legal Judgment and Justice', 1, 'This domain encompasses words related to judicial processes, legal decisions, court proceedings, verdicts, sentences, and the administration of justice, including both the act of judging and the outcomes of legal determinations.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4683, 2459, 'Commands and Decrees', 1, 'Authoritative orders, commandments, and decrees issued by divine or human authorities that require obedience or compliance.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4684, 2458, 'Temple/Sacred Covering', 1, 'Words referring to covering, paneling, or veiling sacred structures, objects, or persons in contexts of worship, holiness, or religious ritual.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4685, 2461, 'Divine Revelation and Signs', 1, 'Words referring to supernatural communication, divine disclosure, and the showing or interpreting of God''s messages, omens, dreams, and prophetic signs.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4686, 2462, 'Warfare and Combat', 1, 'Words relating to engaging in war, waging battle, making war against enemies, or serving as soldiers in military campaigns.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4687, 2459, 'Reflexive and Reciprocal Pronouns', 1, 'Pronouns that refer back to the subject of the clause, including reflexive forms (himself, myself, ourselves) and reciprocal uses (one another, each other).');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4688, 2456, 'Pleasant and Acceptable', 1, 'This domain contains words describing things that are pleasing, pleasant, acceptable, or well-received, particularly in sensory, aesthetic, or relational contexts, including offerings that are acceptable to God.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4689, 2445, 'Sacred-Profane Distinction', 1, 'This domain encompasses words and concepts that distinguish between ceremonially unclean, ritually impure, or profane things versus what is holy, consecrated, or ceremonially pure, particularly in religious and cultic contexts.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4690, 2445, 'Production and Creation', 1, 'This domain encompasses actions of making, constructing, producing, creating, or performing work that results in tangible or intangible artifacts, products, or outcomes.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4691, 2447, 'Burden and Weight', 1, 'This domain encompasses words related to physical and metaphorical burdens, loads, heaviness, and the concepts of being weighed down or being burdensome to others, as well as the associated ideas of honor and gravity derived from weight.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4692, 2448, 'Logical Conjunction Particles', 1, 'Words and particles that express logical relationships, inferences, and conclusions between clauses, including causal connections (because, therefore), temporal sequence (then), and emphatic confirmation (indeed, certainly).');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4693, 2449, 'Nations and Peoples', 1, 'Words referring to groups of people organized as nations, peoples, ethnic groups, or political entities, including both singular nations and collective peoples.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4694, 2458, 'Spreading and Extending', 1, 'This domain encompasses actions of spreading out, stretching forth, or extending something physically, including body parts (hands, wings), objects (nets, garments, coverings), or abstract concepts, often in gestures of prayer, protection, or display.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4695, 2451, 'Killing and Murder', 1, 'This domain encompasses words and expressions related to the act of unlawfully or violently taking human life, including murder, slaying, assassination, and being killed.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4696, 2452, 'Permitting and Leaving Alone', 1, 'This domain covers events where someone allows, permits, or refrains from interfering with another person or situation, including letting something remain as it is or departing from active involvement.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4697, 2453, 'Joint Action and Unity', 1, 'This domain encompasses words describing people, animals, or things acting, moving, existing, or being positioned in unity, as a group, simultaneously, or in the same location.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4698, 2443, 'Large Numbers (Thousands)', 1, 'This domain contains words and expressions for numerical quantities in the thousands, including specific numbers like "two thousand," "three thousand," "five thousand," "seven thousand," and general terms for "thousand" and "ten thousand" (myriad).');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4699, 2455, 'Deception and Deceit', 1, 'This domain encompasses words related to dishonesty, trickery, treachery, and leading others astray through false speech, cunning manipulation, or deliberate misrepresentation of truth.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4700, 2458, 'Approach and Drawing Near', 1, 'This domain encompasses words describing physical, temporal, or relational movement toward a person, place, or deity, including specialized religious contexts of approaching God in worship or bringing offerings.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4701, 2458, 'Moral Standing and Uprightness', 1, 'This domain encompasses words related to taking a moral stand, maintaining ethical integrity, presenting oneself before authority (especially divine), enduring in righteousness, and establishing just principles or covenants.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4702, 2458, 'Anger and Indignation', 1, 'This domain encompasses words expressing emotional states of anger, wrath, indignation, and being vexed or provoked, whether directed at persons, things, or situations.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4703, 2459, 'Sequential Day References', 1, 'Words and expressions that refer to specific days, periods of daytime, or sequential relationships between days (today, tomorrow, the next day, the third day).');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4704, 2458, 'Ritual Tearing and Rending', 1, 'Words describing the violent tearing, rending, or splitting of garments, objects, or bodies, particularly in contexts of religious grief, judgment, or worship response.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4705, 2461, 'Smallness and Scarcity', 1, 'This domain encompasses words describing small quantities, few numbers, brief duration, or something being almost/nearly the case, often emphasizing insignificance or insufficiency in both physical and temporal dimensions.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4706, 2462, 'Rise and Stand Actions', 1, 'Physical actions of rising, standing up, or being raised from a sitting, lying, or deceased position, including literal standing, resurrection, establishing structures or positions, and arising to action.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4707, 2443, 'Sitting and Dwelling', 1, 'Words describing the physical actions of sitting down, being seated, remaining in a place, and dwelling or residing somewhere, including both temporary staying and permanent habitation.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4708, 2444, 'Knowledge and Perception', 1, 'This domain encompasses cognitive processes related to acquiring, possessing, and demonstrating knowledge, including perceiving, understanding, recognizing, and being aware of information or persons.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4709, 2445, 'Fear and Terror', 1, 'This domain encompasses words and expressions related to experiencing fear, dread, terror, or reverent awe, including both natural fear of danger and religious fear/reverence toward God.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4710, 2446, 'Conflict and Strife', 1, 'This domain contains words referring to quarrels, disputes, contentions, fights, and discord between individuals or groups, including verbal arguments and physical confrontations.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4711, 2458, 'Divide and Separate', 1, 'This domain encompasses verbs expressing the action of dividing, splitting, separating, or distributing something into parts or portions, whether physical objects, groups, or abstract entities.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4712, 2453, 'Thin or Emaciated Animals', 1, 'Words describing animals that are physically thin, gaunt, lean, or emaciated in appearance or condition.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4713, 2449, 'Ceasing and Stopping', 1, 'Words related to the cessation, stopping, or ending of activities, processes, or states, including voluntary desisting, coming to an end, causing to cease, and being restrained or prevented from continuing.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4714, 2448, 'Flight and Escape', 1, 'Words relating to fleeing from danger, evading pursuit, escaping from threats or confinement, and seeking refuge or safety through rapid departure.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4715, 2458, 'Dispersal and Scattering', 1, 'This domain contains words referring to the action of spreading, scattering, or dispersing people, objects, or substances across space, including literal scattering (like winnowing grain) and figurative dispersion (like exile of peoples).');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4716, 2447, 'Mourning and Lamentation', 1, 'This domain encompasses ritualized expressions of grief, sorrow, and lamentation, particularly through wailing, dirges, and mourning songs, most commonly performed in response to death or calamity.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4717, 2453, 'Pregnancy and Gestation', 1, 'This domain encompasses body parts and processes related to pregnancy, childbearing, and the reproductive system, including the womb, belly, and conception.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4718, 2454, 'Confession and Repentance', 1, 'Words and expressions used to acknowledge wrongdoing, express remorse, and seek forgiveness from God or other people.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4719, 2455, 'Earth and Land', 1, 'This domain encompasses words referring to the physical earth, ground, soil, land masses, and territories, both as material substance and as geographical/political entities.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4720, 2444, 'Pain and Anguish', 1, 'This domain encompasses words describing physical pain, emotional distress, anguish, and suffering, particularly including labor pains, toil-related suffering, and intense mental or bodily distress.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4721, 2457, 'Moral Folly and Disgrace', 1, 'This domain encompasses terms for foolishness, senselessness, and disgraceful behavior that violates moral, religious, or social standards, often associated with lack of wisdom, shameful acts (especially sexual impropriety), and conduct that brings dishonor.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4722, 2458, 'Visual Attention and Observation', 1, 'This domain encompasses words for directing one''s gaze with intention, particularly looking at, regarding, or observing something or someone with focused attention, often from a specific vantage point or with a particular attitude (favor, concern, contemplation).');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4723, 2450, 'Deficiency and Lack', 1, 'This domain encompasses words describing the state of being without something needed or expected, falling short of a standard or requirement, or having insufficient resources or qualities.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4724, 2455, 'Closing and Shutting', 1, 'Words referring to the physical or metaphorical act of closing, shutting, or blocking openings such as doors, gates, mouths, or other passages, including divine or authoritative restriction of access.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4725, 2461, 'Divine Praise and Worship', 1, 'Words related to praising, lauding, glorifying, and worshiping God or supernatural beings, including acts of verbal acclaim, boasting in the divine, and liturgical expressions of adoration.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4726, 2443, 'Refuge and Shelter', 1, 'Words relating to seeking protection, safety, or asylum from danger, whether literal shelter from elements or figurative refuge in God or sacred places.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4727, 2458, 'Pouring and Casting Actions', 1, 'This domain encompasses verbs describing the physical act of pouring out liquids (water, oil, blood, wine), casting molten metals, making libations, and related metaphorical extensions of these pouring/flowing actions.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4728, 2458, 'Blessing and Happiness', 1, 'This domain encompasses words and expressions related to pronouncing blessings, being in a blessed or happy state, praising God, and experiencing divine or human favor.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4729, 2445, 'Inability to Speak', 1, 'Words describing the condition of being unable to speak or produce sound, whether temporarily (speechless, astonished) or permanently (mute, dumb, deaf-mute), including literal physical conditions and metaphorical states of silence or stupefaction.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4730, 2446, 'Inquiry and Questioning', 1, 'Words related to seeking information through asking questions, making inquiries, or consulting sources including people, deities, or oracles.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4731, 2447, 'Cry Out, Shout', 1, 'Words referring to uttering loud vocal sounds, including shouting, crying out, calling for help, making proclamations, giving battle cries, or expressing distress, joy, or worship through raised voice.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4732, 2448, 'Weakness and Feebleness', 1, 'This domain contains terms describing physical weakness, feebleness, inability to act, languishing, and lacking strength in persons, animals, or things.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4733, 2454, 'Deception and Falsehood', 1, 'This domain encompasses words related to lying, deception, fraud, false testimony, and things that are vain, empty, or misleading, including both the acts themselves and the people who engage in them.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4734, 2445, 'Contempt and Mockery', 1, 'This domain encompasses words describing actions and attitudes of treating others with contempt, scorn, disdain, or mockery, including verbal ridicule and looking down upon others as worthless or inferior.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4735, 2460, 'Life and Recovery', 1, 'This domain encompasses words and expressions related to living, being alive, recovery from illness or near-death, and the preservation of life, including both physical existence and restoration to health or vitality.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4736, 2454, 'Grain and Cereal Crops', 1, 'Words referring to wheat and other grain crops in their various forms (growing plants, harvested kernels, ears of grain) used as food or agricultural products.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4737, 2454, 'Light and Illumination', 1, 'Words referring to physical light from natural or artificial sources, including daylight, luminaries (sun, moon, stars), lamps, and lightning, as well as metaphorical uses of light for life, prosperity, instruction, and divine favor.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4738, 2453, 'Dwelling Places', 1, 'Words referring to places where people or divine beings reside, including physical structures like houses, tents, settlements, and territories, as well as metaphorical or spiritual dwelling places.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4739, 2455, 'Revelation and Disclosure', 1, 'This domain encompasses words related to making hidden or unknown information visible, known, or manifest, including divine revelation, disclosure of secrets, and the unveiling or exposure of previously concealed things.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4740, 2456, 'Written Communication', 1, 'Words referring to written documents, letters, books, and other forms of recorded communication, including both physical objects (scrolls, tablets) and the content they contain (messages, legal documents, sacred texts).');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4741, 2457, 'Speech and Naming', 1, 'Words related to verbal communication, including speaking, saying, telling, commanding, and naming or calling someone/something by a particular designation.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4742, 2458, 'New and Renewed Things', 1, 'Words describing things that are new, fresh, recently made, or recently begun, including physical objects, temporal states, and spiritual renewal.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4743, 2443, 'Divine Judgment and Punishment', 1, 'Physical manifestations of divine authority expressed through afflictive actions such as plagues, beatings, wounds, and destruction that demonstrate God''s power to discipline, punish, or break individuals and nations.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4744, 2460, 'Sending and Dispatching', 1, 'This domain encompasses words related to sending, dispatching, or commissioning persons, objects, or messages from one place or person to another, including both physical sending and abstract commissioning for purposes like divine mission or judgment.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4745, 2454, 'Divine Destruction and Devastation', 1, 'This domain encompasses supernatural or divinely-ordained acts of violent destruction, devastation, and laying waste to cities, nations, and peoples, often as divine judgment or through agents of God''s wrath.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4746, 2458, 'Writing and Inscription', 1, 'This domain encompasses words related to the act of writing, inscribing, or recording text on various surfaces, including composing documents, marking surfaces, registering information, and professional scribal activities.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4747, 2454, 'Implements of Warfare and Destruction', 1, 'Words denoting weapons of war (especially swords and blades), tools of destruction, and states of desolation or devastation resulting from conflict.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4748, 2443, 'External Space and Location', 1, 'Words referring to spaces, places, or locations that are outside of or external to a boundary, structure, or defined area, including streets as outdoor public spaces and the general concept of being positioned beyond an interior or enclosed space.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4749, 2462, 'Distance and Remoteness', 1, 'Words describing spatial distance, remoteness, or being far away from a reference point, including verbs of removing to a distance and adverbs indicating far locations.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4750, 2447, 'Moral Uprightness and Correctness', 1, 'This domain encompasses terms describing moral integrity, ethical straightforwardness, and righteous behavior, as well as things that are correct, proper, or aligned with divine and social standards of righteousness.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4751, 2447, 'Rejection and Refusal', 1, 'This domain encompasses words and expressions related to rejecting, refusing, dismissing, or setting aside something or someone, whether objects, people, ideas, laws, or opportunities, ranging from simple refusal to contemptuous rejection.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4752, 2444, 'Parts and Portions', 1, 'Words referring to divisions, sections, shares, or allocated parts of a whole, including portions of land, food, inheritance, or abstract divisions.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4753, 2460, 'Beds and Couches', 1, 'This domain includes words for furniture used for sleeping, resting, or reclining, such as beds, couches, pallets, and mattresses.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4754, 2454, 'Wild Animals - Lions', 1, 'Words referring to lions, large predatory felines that are prominent in biblical imagery both literally and metaphorically.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4755, 2451, 'Death and Dying', 1, 'Words and expressions related to the cessation of life, including natural death, violent death, execution, and the state of being dead.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4756, 2452, 'Hearing and Obeying', 1, 'Words and expressions related to perceiving sound through the ears, listening attentively, and responding with compliance or obedience to what is heard.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4757, 2455, 'Confinement and Restraint', 1, 'This domain encompasses actions involving restricting freedom of movement, withholding, or keeping something or someone from proceeding, whether through physical imprisonment, internal compulsion, or prevention of action.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4758, 2454, 'Peace and Greeting', 1, 'Words related to peace as both a state of being (absence of conflict, harmony, well-being) and as a communicative act (greetings, inquiries about welfare, and establishing peaceful relations).');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4759, 2458, 'Lying and Reclining', 1, 'This domain covers words describing the physical act of lying down, reclining, or being in a horizontal position, whether for rest, sleep, illness, death, or burial, as well as the metaphorical extension to things being placed, established, or situated in a location.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4760, 2456, 'Guard and Preserve', 1, 'This domain encompasses words related to carefully watching over, protecting, maintaining, and observing things or people, including keeping commands, guarding against danger, and treasuring memories or truths in one''s heart.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4761, 2457, 'Proclamation and Declaration', 1, 'This domain encompasses words related to the public or formal announcement, declaration, and proclamation of information, news, or messages, including both secular reporting and religious preaching.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4762, 2452, 'Abandonment and Neglect', 1, 'This domain encompasses actions of leaving behind, forsaking, ignoring, or rejecting people, places, responsibilities, or relationships, whether temporarily or permanently.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4763, 2444, 'Cognitive Understanding', 1, 'This domain encompasses mental processes of perceiving, comprehending, discerning, and making sense of information, whether through sensory perception or intellectual apprehension, as well as teaching others to understand.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4764, 2460, 'Nets and Fishing Tools', 1, 'This domain contains words referring to various types of nets used for fishing, hunting, or trapping, including literal nets and metaphorical uses representing entrapment or judgment.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4765, 2461, 'Spiritual Bonds and Chains', 1, 'Physical restraints such as bonds, chains, fetters, and binding obligations that are used metaphorically in supernatural or theological contexts to represent spiritual bondage, divine judgment, or liberation from oppression.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4766, 2462, 'God and Divinity', 1, 'Words referring to God, gods, divine beings, and deity-related attributes including the true God of Israel, pagan deities, angels, and terms describing godly or divine characteristics.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4767, 2443, 'Bringing People In', 1, 'Words referring to the action of leading, bringing, or introducing people into a place, dwelling, court, or into the presence of others.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4768, 2454, 'Service and Labor', 1, 'This domain encompasses actions of serving, working for, or ministering to others, including labor, worship, servitude, and cultivation, whether directed toward people, deities, or the land.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4769, 2455, 'Tree branches and boughs', 1, 'This domain contains words referring to the branches, boughs, shoots, and fruit-stalks of trees and plants, including both literal references to plant structures and metaphorical uses in biblical imagery.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4770, 2446, 'Willingness and Desire', 1, 'This domain encompasses expressions of volition, willingness, consent, pleasure, and desire—whether human or divine—including both positive inclination toward something and the determination to act upon that inclination.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4771, 2445, 'Luxurious and Precious Things', 1, 'This domain encompasses valuable, costly, and highly prized objects, including precious stones, expensive foods, and luxurious items that are either rare, beautiful, or of high monetary worth.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4772, 2448, 'Rain and Precipitation', 1, 'Words referring to rain, showers, and different types of seasonal precipitation, including early rain, latter rain, heavy downpours, and the act of causing rain to fall.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4773, 2454, 'Cities and Urban Settlements', 1, 'Words referring to cities, towns, fortified settlements, and related urban concepts including citadels, city-states, and their inhabitants.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4774, 2456, 'Exhaustion and Weariness', 1, 'This domain encompasses terms describing the physical and emotional state of being tired, fatigued, or worn out from exertion, labor, or hardship.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4775, 2456, 'Red and Scarlet Colors', 1, 'This domain contains words referring to the colors red and scarlet, including shades ranging from crimson to fiery red, whether describing natural objects, dyed materials, or symbolic uses.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4776, 2451, 'Sexual Immorality Events', 1, 'Events and acts of sexual misconduct including fornication, prostitution, adultery, incest, and metaphorically extended to idolatry as spiritual unfaithfulness.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4777, 2454, 'Inheritance and Possession', 1, 'This domain encompasses words related to receiving, distributing, or holding property, land, or rights through inheritance, allotment, or divine assignment, including the transfer of possessions from one generation to another.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4778, 2454, 'Meeting and Encountering', 1, 'This domain encompasses words related to physically meeting or encountering someone or something, whether intentionally (going out to meet) or by chance, as well as figurative uses describing events that befall or happen to someone.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4779, 2454, 'Precious Metals and Gold', 1, 'This domain contains words referring to gold as a precious metal, including various types, qualities, and forms of gold, as well as gold ornaments and objects made from gold.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4780, 2448, 'Excessive Degree and Comparison', 1, 'This domain encompasses words expressing comparative and superlative degrees of quantity, intensity, or extent, particularly indicating surplus, excess, or going beyond normal limits, often conveying emotional intensity through extremity of measure.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4781, 2457, 'Authority and Rule', 1, 'This domain encompasses words related to the legitimate power, authority, or right to command, govern, or exercise control over others, including both the abstract concept of authority and concrete expressions of rule through offices, jurisdictions, and governing powers.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4782, 2458, 'Trust and Faithfulness', 1, 'This domain encompasses concepts related to trust, belief, faithfulness, reliability, and confidence in persons, things, or divine beings, including the qualities of being trustworthy and the actions of relying on or having faith in someone or something.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4783, 2459, 'Divine Radiance and Glory', 1, 'This domain encompasses words describing the shining, glowing, or radiating of light—particularly divine light or glory—that manifests God''s presence, favor, and authority, often metaphorically representing spiritual illumination or the visible expression of divine power.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4784, 2460, 'Divine Spirit and Supernatural Beings', 1, 'This domain encompasses concepts related to the Holy Spirit, human inner life and disposition, supernatural entities (both divine and evil spirits), and the spiritual dimension that transcends physical reality.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4785, 2461, 'Divine Preparation and Construction', 1, 'Words referring to preparing, constructing, equipping, or establishing something according to God''s purposes or by divine agency, especially things related to salvation, judgment, or God''s redemptive plan.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4786, 2447, 'Rebellion and Sedition', 1, 'Words referring to acts of defection, apostasy, revolt, insurrection, or opposition against established religious or political authority.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4787, 2458, 'Separated Person', 1, 'A person who has been set apart, distinguished, or separated from others, either physically, socially, religiously, or in divine purpose.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4788, 2444, 'Shepherd and Flock Care', 1, 'This domain encompasses activities and roles related to tending, pasturing, and caring for livestock (especially sheep), including both literal shepherding and metaphorical leadership or guidance of people.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4789, 2454, 'Pasture and Grazing Land', 1, 'This domain encompasses words referring to land used for grazing livestock, including pastures, meadows, open grazing areas, and the common lands surrounding settlements where animals feed.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4790, 2446, 'Completion and Fulfillment', 1, 'This domain encompasses words relating to bringing something to its full measure, completion, or intended state, including fulfilling prophecies, completing tasks or periods of time, and filling containers or spaces to capacity.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4791, 2454, 'Stone and Rock Materials', 1, 'Words referring to stone, rock, and similar hard mineral materials in their natural state or as worked materials, including precious stones, building stones, and stone-like objects.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4792, 2448, 'Locational Adverbs', 1, 'Words that indicate location, direction, or spatial position such as "there," "here," "thither" (to that place), and "thence" (from that place).');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4793, 2444, 'Behind and After', 1, 'Words expressing spatial position behind something or someone, backward direction, and temporal sequence occurring after another event.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4794, 2455, 'Personal Care and Protection', 1, 'This domain encompasses actions of adorning, anointing, caring for, protecting, and redeeming persons, including physical beautification, ritual anointing, divine protection, and rescue from harm or bondage.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4795, 2451, 'Wealth and Riches', 1, 'This domain contains words referring to material wealth, possessions, treasures, and financial resources that individuals, cities, or nations accumulate.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4796, 2456, 'Interior Spatial Location', 1, 'Words describing position, movement, or orientation toward or within the inside of a bounded space, as opposed to outside or beyond its boundaries.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4797, 2443, 'Shame and Disgrace', 1, 'This domain encompasses actions and experiences related to feeling shame, being disgraced, or causing others to feel ashamed or humiliated, whether before people or God.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4798, 2454, 'Lower Position and Depth', 1, 'Words describing spatial positions that are lower, beneath, or at the bottom of something, including physical locations, architectural levels, and metaphorical depths.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4799, 2444, 'Walls and Fortifications', 1, 'Physical structures that enclose, protect, or divide spaces, including city fortifications, building walls, and barriers that provide defense or separation.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4800, 2454, 'Religious Assembly and Congregation', 1, 'This domain encompasses terms for formal gatherings of religious communities, including assemblies, churches, and congregations, particularly referring to organized groups called together for religious purposes in Jewish and Christian contexts.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4801, 2455, 'Divine Visitation and Judgment', 1, 'This domain encompasses words describing God''s attentive observation of people or situations, whether for gracious intervention, inspection and testing, or punitive judgment, often including the associated actions of mustering, appointing overseers, or bringing consequences upon wrongdoing.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4802, 2458, 'Similarity and Likeness', 1, 'Words expressing resemblance, comparison, or similarity between entities, whether in appearance, quality, or nature.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4803, 2454, 'Oppression and Exploitation', 1, 'This domain encompasses words describing the exercise of unjust or cruel authority through oppression, mistreatment, extortion, and wrongful exercise of power over others, particularly targeting the vulnerable such as the poor, strangers, and powerless.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4804, 2454, 'Anointing Oil Offerings', 1, 'This domain covers words relating to oil, particularly olive oil and fresh oil, used in religious contexts for anointing, tithing, and as offerings to priests and Levites.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4805, 2454, 'Neighbor and Fellow Human', 1, 'Words referring to other human beings with whom one has social relationships, obligations, or proximity, including neighbors, friends, companions, associates, and fellow members of one''s community.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4806, 2449, 'Quietness and Ease', 1, 'This domain contains words describing states of tranquility, peace, prosperity, and freedom from disturbance or anxiety, whether applied to persons, nations, lands, or situations.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4807, 2445, 'Appointment and Preparation', 1, 'This domain encompasses actions related to establishing, appointing, preparing, or arranging people, things, or circumstances for a particular purpose or role.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4808, 2444, 'Commercial Transaction', 1, 'Words related to acquiring goods or property through purchase, trade, or exchange, including buying, selling, and commercial transactions in markets.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4809, 2455, 'Rapid Movement and Action', 1, 'This domain encompasses words describing quick, hurried, or urgent movement and action, including rushing, hastening, acting decisively or rashly, and fleeing in panic.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4810, 2446, 'Visible and Evident', 1, 'Words describing things that are clearly visible, openly manifest, easily perceived, or publicly known rather than hidden or secret.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4811, 2443, 'Interjections of Distress', 1, 'Exclamations expressing emotional pain, grief, lamentation, or dismay, typically translated as "Alas!", "Ah!", "Ha!", or "Woe!"');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4812, 2448, 'Ritual Purification and Refining', 1, 'This domain encompasses actions and agents involved in cleansing, purifying, or refining substances and persons, whether through physical processes (like smelting metals), ceremonial rituals (like washing for religious purity), or moral/spiritual purification.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4813, 2454, 'Poverty and Neediness', 1, 'Words describing people who lack material resources, wealth, or social power, including those who are economically poor, socially oppressed, or in need of help and deliverance.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4814, 2450, 'Pride and Arrogance', 1, 'Words describing excessive self-elevation, presumptuous behavior, and haughty attitudes that exalt oneself above others or against God.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4815, 2451, 'Priesthood and Priests', 1, 'Words relating to priests, priestly service, and the office of the priesthood across various religious traditions, including cultic officials who perform sacrifices, mediate between deity and people, and conduct religious rituals.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4816, 2444, 'Mental and Emotional States', 1, 'This domain encompasses words referring to the inner person—the heart, mind, will, and emotions—as the seat of thought, intention, moral character, feelings, and decision-making.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4817, 2453, 'ACTION_231', 1, 'Auto-detected community 11173 with 19 senses');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4818, 2443, 'SPEECH_232', 1, 'Auto-detected community 23889 with 19 senses');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4819, 2455, 'COGNITION_233', 1, 'Auto-detected community 2195 with 19 senses');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4820, 2453, 'EMOTION_234', 1, 'Auto-detected community 9825 with 19 senses');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4821, 2457, 'MORAL_235', 1, 'Auto-detected community 15302 with 19 senses');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4822, 2456, 'SOCIAL_236', 1, 'Auto-detected community 10157 with 19 senses');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4823, 2459, 'AUTHORITY_237', 1, 'Auto-detected community 9568 with 19 senses');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4824, 2444, 'WORSHIP_238', 1, 'Auto-detected community 1067 with 19 senses');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4825, 2453, 'SUPERNATURAL_239', 1, 'Auto-detected community 5530 with 19 senses');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4826, 2454, 'QUANTITY_240', 1, 'Auto-detected community 3748 with 19 senses');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4827, 2460, 'PERSON_241', 1, 'Auto-detected community 14433 with 19 senses');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4828, 2444, 'BODY_242', 1, 'Auto-detected community 7008 with 19 senses');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4829, 2445, 'LOCATION_243', 1, 'Auto-detected community 14136 with 19 senses');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4830, 2456, 'ARTIFACT_244', 1, 'Auto-detected community 8717 with 19 senses');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4831, 2454, 'FOOD_DRINK_245', 1, 'Auto-detected community 11574 with 19 senses');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4832, 2460, 'Forgetting and Being Forgotten', 1, 'Words relating to the mental process of forgetting information, people, commands, or obligations, as well as being forgotten by others or falling into oblivion.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4833, 2444, 'PLANT_247', 1, 'Auto-detected community 15701 with 18 senses');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4834, 2447, 'NATURAL_WORLD_248', 1, 'Auto-detected community 12754 with 18 senses');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4835, 2443, 'TIME_249', 1, 'Auto-detected community 2666 with 18 senses');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4836, 2452, 'EVENT_250', 1, 'Auto-detected community 3550 with 18 senses');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4837, 2460, 'Forceful Expulsion and Removal', 1, 'Actions involving forcefully driving out, casting away, or banishing people, objects, or entities from a place or position, including exile, ejection, and violent removal.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4838, 2454, 'Messengers and Angels', 1, 'This domain encompasses beings who carry messages or announcements, including human messengers, envoys, and supernatural beings such as angels who communicate divine will.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4839, 2454, 'Sky and Heavens', 1, 'This domain encompasses terms for the visible sky, firmament, clouds, and celestial realm, including both the physical atmosphere where birds fly and celestial bodies exist, as well as the spiritual dwelling place of the divine.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4840, 2458, 'Amazement and Astonishment', 1, 'This domain encompasses emotional states of being overwhelmed by wonder, shock, or surprise, ranging from positive marvel to fear-tinged bewilderment, often in response to extraordinary or unexpected events.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4841, 2454, 'Lush Vegetation', 1, 'Words describing trees, plants, and foliage that are thick, leafy, fresh, luxuriant, or flourishing with abundant growth.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4842, 2456, 'Desire and Longing', 1, 'This domain encompasses words expressing intense desire, longing, or craving for something or someone, ranging from neutral yearning to coveting and lustful desire.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4843, 2459, 'Bovine Livestock Animals', 1, 'This domain contains terms for cattle and related bovine animals, including bulls, cows, oxen, heifers, and collective terms for herds, used in contexts of property, labor, sacrifice, and metaphorical expressions of strength or value.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4844, 2454, 'Clay and Pottery Materials', 1, 'This domain encompasses words related to clay, mud, mortar, earthenware, and pottery materials used in construction, vessel-making, and metaphorical descriptions of human fragility or divine creative power.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4845, 2461, 'Money and Wealth', 1, 'This domain encompasses words related to money, silver, monetary transactions, attitudes toward wealth (both loving and not loving money), and financial sums or capital.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4846, 2458, 'Conditional/Temporal Markers', 1, 'Words and particles that introduce conditional or temporal clauses, indicating when, if, or under what circumstances an action or state occurs.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4847, 2450, 'Mental Activity and Cognition', 1, 'This domain encompasses verbs and expressions related to mental processes such as thinking, considering, reasoning, supposing, believing, and forming opinions or judgments about people, situations, or ideas.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4848, 2454, 'Incense and Fragrant Offerings', 1, 'This domain encompasses frankincense, incense, and aromatic substances burned in religious rituals and offerings, including the trees that produce them, the act of burning them, and the smoke they produce.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4849, 2454, 'Idols and False Gods', 1, 'This domain encompasses carved images, idols, false gods, and places of idol worship that are objects of religious veneration outside of true worship.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4850, 2446, 'Economic Exchange and Reciprocity', 1, 'This domain encompasses actions of giving, returning, repaying, or exchanging goods, services, debts, and rewards, including both material transactions (selling, paying debts) and abstract reciprocal actions (recompense, retribution, yielding results).');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4851, 2458, 'Running and Swift Movement', 1, 'Words describing rapid physical movement, particularly running, rushing, or moving swiftly from one place to another, including both human and animal motion.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4852, 2444, 'Miscellaneous Terms', 1, 'An incorrectly grouped collection containing both maritime vessels (ships) and first-person pronouns (I, we) that share no semantic relationship.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4853, 2449, 'Ability and Power', 1, 'Words expressing capacity, capability, or power to do something, including being able, prevailing over opposition, or enduring difficulty.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4854, 2446, 'Violent Physical Destruction', 1, 'This domain encompasses words describing violent physical force that crushes, shatters, or breaks apart objects or people, often used metaphorically for oppression or divine judgment.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4855, 2456, 'Wealth and Prosperity', 1, 'Words describing the state of being wealthy, the process of becoming rich or making others rich, and those who possess abundant material resources.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4856, 2446, 'Third and Tripartite Division', 1, 'This domain encompasses words and expressions related to the ordinal number "third," the cardinal number "three," and actions involving division into three parts or repetition three times.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4857, 2454, 'Spears and Javelins', 1, 'This domain encompasses offensive weapons consisting of long shafts with pointed heads, including spears, lances, javelins, and darts used in combat and warfare.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4858, 2450, 'Stubborn Rebellion', 1, 'Words describing stubborn, rebellious, or apostate behavior, particularly in refusing to obey God or legitimate authority.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4859, 2444, 'Teaching and Learning', 1, 'This domain encompasses words related to the transmission and acquisition of knowledge, including activities of instruction, education, training, and study, as well as the roles of teachers and students.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4860, 2456, 'Emotion: Hope and Expectation', 1, 'This domain encompasses expressions related to the emotional states of hoping, expecting, or anticipating that certain events will occur or that particular states will come into being, including wishes and prayers for outcomes.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4861, 2457, 'Desire and Favor', 1, 'This domain encompasses words relating to wanting, wishing, desiring something, as well as expressions of goodwill, pleasure, acceptance, and favorable disposition toward someone or something.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4862, 2458, 'Pits and Excavations', 1, 'This domain contains words referring to holes, pits, and excavations in the ground, whether dug for trapping animals, used figuratively for danger and calamity, or referring to the pit of Sheol (the realm of the dead).');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4863, 2459, 'Righteousness and Justice', 1, 'This domain encompasses concepts related to moral uprightness, ethical conduct, legal correctness, and fairness in judgment, whether attributed to persons, actions, God, or communities.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4864, 2460, 'Removing Sacrificial Animals', 1, 'Words relating to the physical act of leading away or carrying off animals, objects, or persons in contexts involving worship, sacrifice, or religious rituals.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4865, 2443, 'Supernatural Form/Appearance', 1, 'Words describing the visible form, shape, appearance, or manifestation of supernatural beings, divine entities, or spiritual visions, including both their physical representation and their essential nature.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4866, 2462, 'Fittingness and Propriety', 1, 'This domain encompasses concepts of appropriateness, suitability, and what is proper or seemly in a given context, whether morally, socially, or circumstantially fitting.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4867, 2443, 'Blameless and Unblemished', 1, 'This domain contains terms describing persons who are morally irreproachable, without fault or defect, either in character (blameless, having integrity) or in physical condition (without blemish, as required for priests or sacrificial animals).');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4868, 2454, 'Body Parts and Fragments', 1, 'This domain encompasses words referring to pieces, fragments, or portions of bodies (whether human, animal, or objects), including torn garments, divided carcasses, broken pieces, and dismembered limbs.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4869, 2445, 'Participation and Sharing', 1, 'Words relating to partaking in, sharing, or having fellowship with something or someone, including concepts of joint ownership, partnership, and communal involvement.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4870, 2455, 'Honor and Glory', 1, 'This domain encompasses concepts related to being glorified, honored, wealthy, or noble, as well as actions of honoring, hardening hearts, and self-glorification, primarily expressed through various forms of the Hebrew root כבד (kbd) and related terms.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4871, 2447, 'Vertical Position and Direction', 1, 'Words describing upward spatial orientation, elevation, or position above a reference point, including both static location (above, upper) and directional movement (upward), as well as temporal or hierarchical extensions of these spatial concepts.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4872, 2448, 'Temporal Continuation and Repetition', 1, 'Words expressing ongoing temporal states (still, yet, while), repetition or addition of actions (again, more), and contrasts with previous states (no longer, besides).');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4873, 2449, 'Binding and Wrapping', 1, 'This domain encompasses actions involving tying, binding, wrapping, or securing objects or people with cords, cloth, or other materials, including both literal applications (binding wounds, tying animals, imprisoning) and metaphorical uses (binding obligations, wrapping in secrecy).');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4874, 2445, 'Stoning and Stone-Throwing', 1, 'This domain contains words related to the act of throwing stones at someone or something, particularly the practice of stoning as a form of punishment or execution.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4875, 2455, 'Narrate and Recount', 1, 'Words referring to telling, recounting, narrating, or describing events, stories, or information in detail to others.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4876, 2452, 'Measurement and Measuring', 1, 'This domain encompasses words related to the act of measuring, units of measurement (for length, volume, capacity), dimensions, size, stature, and measured portions or extents.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4877, 2452, 'Permission and Authorization', 1, 'Words describing the action of granting permission, allowing something to happen, or giving authorization for someone to do something.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4878, 2454, 'Evidence and Proof', 1, 'Words referring to evidence, proof, demonstration, or testing used to establish truth, refute claims, or verify character and claims through argument or trial.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4879, 2446, 'First and Former', 1, 'This domain encompasses concepts of temporal priority, including ordinal firstness in sequence, previous or earlier states/events, ancestors, and initial positions in time or rank.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4880, 2456, 'Sufficiency and Enough', 1, 'This domain encompasses expressions indicating that something is adequate, sufficient, or has reached a satisfactory level, including declarations that no more is needed or desired.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4881, 2457, 'Messages and Reports', 1, 'Words referring to information communicated from one party to another, including news, tidings, announcements, proclamations, prophetic messages, and reports about events or people.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4882, 2446, 'Frequency and Repetition', 1, 'This domain contains words and expressions that indicate how many times an action or event occurs, including specific numbers of occurrences (once, twice, seven times) and general frequency (often, how many times).');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4883, 2455, 'Forceful Drawing and Compelling', 1, 'Words describing the act of physically pulling, dragging, or drawing something or someone with force, or metaphorically compelling, attracting, or bringing people under one''s influence or control.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4884, 2462, 'War and Battle', 1, 'Words referring to armed conflict, military campaigns, warfare, battles, and combat between opposing forces.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4885, 2457, 'Theological Disputation', 1, 'Words referring to religious or theological debate, discussion, and argumentation, particularly about scriptural interpretation and doctrinal matters.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4886, 2458, 'Sweet and Pleasant', 1, 'This domain encompasses words describing sweet taste, pleasant sensory experiences, and agreeable qualities, both literal (like honey or fresh water) and figurative (like pleasant words or intimate relationships).');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4887, 2458, 'Clothed Person', 1, 'This domain contains words and expressions that describe people in terms of what they are wearing or how they have been dressed by themselves or others.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4888, 2455, 'Humble and Lower Oneself', 1, 'This domain contains words describing the physical or spiritual act of making oneself or being made lower in position, status, or attitude, particularly in relation to God or others, including both voluntary humility and forced subjugation.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4889, 2451, 'Adversaries and Enemies', 1, 'This domain encompasses words referring to people or entities who oppose, hate, or act hostilely toward someone, including personal foes, national enemies, military adversaries, and supernatural opponents like Satan.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4890, 2444, 'Signs and Markers', 1, 'Physical marks, symbols, or objects used to identify, signal, memorialize, prove, or communicate information, including miraculous signs, tokens, standards, monuments, and inscriptions.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4891, 2447, 'East Direction', 1, 'Words referring to the eastern direction, the place where the sun rises, including references to east wind, eastern locations, and movement toward the east.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4892, 2454, 'Price and Value', 1, 'Words referring to the monetary cost, economic worth, or market value of goods and services, including hire, compensation, and what must be paid to acquire something.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4893, 2446, 'Early Rising and Morning Activity', 1, 'Words and expressions related to waking up early in the morning, rising at dawn, or taking action in the early hours of the day.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4894, 2454, 'South and Southern Direction', 1, 'Words referring to the southern cardinal direction, the south wind, the southern region (especially the Negeb), and midday (when the sun is in the south).');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4895, 2451, 'Departure and Withdrawal', 1, 'Words referring to the action of leaving a place, withdrawing from a situation, or physically removing oneself from a location or circumstance.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4896, 2445, 'Stumbling and Falling', 1, 'Events involving loss of balance, tripping, or stumbling, either literally (physical stumbling) or figuratively (moral/spiritual failure, taking offense, or being overthrown).');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4897, 2455, 'Work and Labor', 1, 'This domain encompasses words related to performing physical or mental work, laboring, toiling, and engaging in productive activities, including the exertion and weariness that may result from such efforts.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4898, 2454, 'Help and Assistance', 1, 'Words referring to providing aid, support, or assistance to someone in need, including coming to someone''s rescue or defense.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4899, 2452, 'Exception and Exclusion', 1, 'Words and phrases that indicate something is excluded from a statement or action, or that mark an exception to what has been said, typically meaning "except," "unless," "apart from," or "besides."');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4900, 2456, 'Abyss and Deep Waters', 1, 'This domain encompasses words referring to vast, unfathomable depths—including ocean abysses, primordial cosmic waters, subterranean sources, and the underworld—often evoking feelings of awe, mystery, or terror associated with the unknowable deep.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4901, 2457, 'Treasure and Wealth Storage', 1, 'This domain encompasses physical treasures, valuable possessions, and the places where such wealth is stored or kept, including treasuries, storehouses, and treasure chambers.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4902, 2443, 'Prosperity and Fatness', 1, 'This domain encompasses words describing physical abundance, fatness, and robustness in people, animals, land, and food, often connoting prosperity, wealth, and well-being in social contexts.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4903, 2459, 'Divine Illumination and Revelation', 1, 'Words relating to God giving light, enlightening minds, making truth known, or causing His presence to shine forth, often with connotations of blessing, favor, instruction, or spiritual awakening.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4904, 2448, 'Divine Mercy and Compassion', 1, 'Words expressing the showing or receiving of mercy, compassion, and pity, particularly in the context of divine-human relationships and worship.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4905, 2446, 'Salvation and Deliverance', 1, 'This domain encompasses divine or supernatural acts of saving, rescuing, healing, and delivering people from physical danger, spiritual peril, sickness, or death, particularly through God''s intervention or power.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4906, 2454, 'Prayer and Petition', 1, 'Words referring to requests, petitions, intercessions, and prayers directed to God or deities, including both general prayer and specific supplications.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4907, 2445, 'Washing and Cleansing', 1, 'This domain encompasses words related to the physical act of washing, bathing, laundering, and rinsing various objects (clothing, body parts, or the entire body) and the agents who perform these actions.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4908, 2444, 'Anointing and Smearing', 1, 'This domain covers actions of applying oil, ointment, or other substances to the skin or surfaces, including ceremonial anointing, post-bathing care, medicinal application, and general coating or plastering.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4909, 2451, 'Wine and Fermented Beverages', 1, 'This domain includes words referring to wine, new wine, must, and other fermented grape juice used for drinking, celebration, religious offerings, and intoxication.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4910, 2446, 'Right Side and Hand', 1, 'Words referring to the right hand as a body part, the right side as a direction or position, movement toward the right, and related concepts of dexterity or favor associated with the right side.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4911, 2458, 'Temporal Reference and Inquiry', 1, 'Words and particles used to ask about or refer to points in time, whether definite, indefinite, past, future, or hypothetical.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4912, 2444, 'Secrecy and Concealment', 1, 'This domain encompasses words and phrases describing actions, states, or locations characterized by hiddenness, privacy, stealth, or concealment from view or knowledge.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4913, 2454, 'Disciples and Teaching', 1, 'This domain encompasses words related to learners, pupils, disciples, and those who have been taught or instructed, particularly in religious or philosophical contexts.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4914, 2446, 'Vengeance and Punishment', 1, 'This domain contains words related to avenging wrongs, taking vengeance, punishing offenses, and exacting retribution for injuries or violations.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4915, 2454, 'Religious Service', 1, 'Words referring to sacred duties, religious ministry, and acts of worship performed in service to God, particularly in the context of the tabernacle, temple, or church.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4916, 2452, 'Redemption and Release', 1, 'Words referring to the act of setting free, ransoming, or delivering someone or something from bondage, debt, guilt, or obligation, often through payment of a price.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4917, 2445, 'Pledging and Collateral', 1, 'This domain encompasses words related to the practice of taking, giving, or holding pledges and securities as collateral for debts or loans, including the physical items pledged and the actions of pledging.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4918, 2454, 'Physical Contact Communication', 1, 'Words describing physical touching or reaching that serves as a means of communication, connection, or conveying intention between people or with objects.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4919, 2455, 'Deception and Trickery', 1, 'This domain encompasses cognitive acts of deliberately misleading, deceiving, or defrauding others through false reasoning, cunning schemes, or dishonest manipulation of beliefs.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4920, 2444, 'Hope and Expectation', 1, 'This domain encompasses emotional states and expressions related to anticipating positive future outcomes, including confident expectation, trust in future possibilities, and the objects or reasons for such hopeful anticipation.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4921, 2458, 'Adhesion and Attachment', 1, 'This domain encompasses words describing physical clinging, sticking, or adhering of objects to surfaces, as well as metaphorical attachment through loyalty, devotion, or joining oneself to a person, group, or cause.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4922, 2446, 'First Person Plural Pronouns', 1, 'Words that refer to a group of people that includes the speaker, expressing "we," "us," or "our" in various grammatical forms and contexts.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4923, 2447, 'Sickness and Disease', 1, 'This domain encompasses words referring to physical or mental illness, ailments, afflictions, and conditions that compromise health or well-being, including metaphorical uses of disease to describe social or spiritual maladies.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4924, 2454, 'Hostility and Aversion', 1, 'This domain encompasses words and expressions related to intense dislike, hatred, enmity, and rejection toward persons, actions, or things, ranging from personal animosity to divine rejection of evil.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4925, 2461, 'Divine and Ancestral Lineage', 1, 'This domain encompasses terms related to parentage, ancestry, and divine fatherhood, including biological parents, forefathers, tribal heads, and God as Father, reflecting both human genealogical relationships and supernatural divine-human connections.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4926, 2443, 'Personal Names', 1, 'This domain contains proper names of individuals mentioned in biblical texts, including historical figures, family heads, and individuals associated with specific events or locations.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4927, 2454, 'Fervent Zeal and Jealousy', 1, 'This domain encompasses intense emotional states involving passionate devotion, competitive rivalry, possessive jealousy, and envious resentment, whether directed positively (zeal, ardor) or negatively (envy, jealous anger).');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4928, 2443, 'Strength and Power Symbols', 1, 'This domain encompasses physical objects and metaphorical imagery used to represent strength, power, authority, and dignity, particularly horns as symbols of might in both literal and figurative contexts.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4929, 2445, 'Daniel (Prophet/Person)', 1, 'This domain contains references to Daniel, a biblical name meaning "God is my judge," referring to various individuals including the famous prophet taken into Babylonian captivity, a son of David, a priest, and a renowned sage.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4930, 2454, 'Verbal Encouragement and Counsel', 1, 'Words referring to spoken or written forms of encouragement, exhortation, consolation, admonition, and appeals intended to influence, comfort, or guide others.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4931, 2454, 'Crowd and Multitude', 1, 'This domain contains words referring to large groups or masses of people, animals, or things, including crowds, throngs, mobs, assemblies, and abundant quantities.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4932, 2448, 'Defense and Alternation', 1, 'Words related to defending oneself through speech or legal proceedings, and concepts of alternating, changing, or taking turns in shifts or relays.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4933, 2454, 'Levi and Levites', 1, 'Terms referring to Levi (son of Jacob and Leah), his descendants as a tribe, and the Levites as a priestly class set apart for religious service in Israel.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4934, 2450, 'Memory and Memorial', 1, 'Words referring to the mental faculty of remembering, the act of recollection, commemorative practices, physical objects or written records that serve as reminders, and mentions or references to past events or persons.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4935, 2454, 'Ancient Tyre References', 1, 'This domain contains references to the ancient Phoenician city of Tyre, including its name, inhabitants (Tyrians), and related expressions used in historical, prophetic, and geographical contexts.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4936, 2450, 'Pride and Arrogance', 1, 'Words describing people who are excessively proud, boastful, arrogant, presumptuous, or haughty in their attitude and behavior, often in opposition to God or proper humility.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4937, 2454, 'Proper Names: Jonathan', 1, 'This domain contains various inflected forms and contextual uses of the Hebrew proper name "Jonathan" (Yehonatan/Yonatan), meaning "YHWH has given," referring to multiple biblical individuals including Saul''s son, priests, Levites, and other historical figures.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4938, 2454, 'Presenting Offerings', 1, 'Words related to bringing, presenting, offering, or entrusting sacrifices, gifts, food, or other items to deities, authorities, or other people, often in formal or ritual contexts.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4939, 2455, 'Spatial and Relational Proximity', 1, 'This domain encompasses words describing physical nearness, spatial adjacency, close relational connections (kinship, neighbors), temporal proximity, and spiritual nearness to God.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4940, 2462, 'Hunger and Famine', 1, 'This domain includes words related to the physical sensation of hunger, the state of being hungry, widespread food shortages (famine), and the causation of hunger.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4941, 2457, 'Love and Affection', 1, 'This domain encompasses words expressing love, affection, and emotional attachment between persons (human to human, human to divine, divine to human), including romantic love, friendship, familial love, and the physical expressions of love such as kissing.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4942, 2458, 'Numbers and Counting', 1, 'Words referring to the cardinal number ten and its uses in counting, enumerating people or objects, and forming compound numbers.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4943, 2447, 'Rebellion Against Authority', 1, 'Words referring to acts of rebellion, transgression, or violations against established authority (divine, legal, or interpersonal), including the guilt and punishment associated with such acts.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4944, 2455, 'Confession and Proclamation', 1, 'Words referring to publicly declaring, confessing, acknowledging, or proclaiming something, especially in a religious or worship context, including confessing sins, declaring God''s attributes, making vows, or giving testimony.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4945, 2454, 'Gentile/Greek Identity', 1, 'This domain encompasses terms referring to Greeks (Hellenes) and by extension Gentiles, identifying people who are culturally Greek or ethnically non-Jewish in the context of the New Testament.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4946, 2454, 'Edom and Edomites', 1, 'Words referring to Edom (both as a person, the descendants of Esau, and as a geographical region), including the compound name Obed-Edom.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4947, 2454, 'Descendants and Offspring', 1, 'Words referring to biological descendants, offspring, lineage, or seed—whether literal agricultural seed, human progeny, or extended family lines and future generations.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4948, 2444, 'Pain and Sorrow', 1, 'This domain encompasses terms for both physical pain and emotional grief, including words for sorrow, mental anguish, vexation, and hurt that affect body or mind.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4949, 2445, 'Knowledge and Understanding', 1, 'This domain encompasses words relating to knowledge, understanding, discernment, wisdom, and the cognitive capacity to perceive, recognize, or comprehend information, particularly in moral, spiritual, or intellectual contexts.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4950, 2444, 'Removal and Displacement', 1, 'Words related to physically removing, taking away, departing from, or displacing objects, people, or abstract things from their original location or state.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4951, 2447, 'Suddenness and Immediacy', 1, 'This domain contains adverbs and expressions describing events that occur suddenly, unexpectedly, or instantaneously, without warning or preparation.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4952, 2448, 'Brightness and Gleaming', 1, 'Words describing things that shine, flash, gleam, or emit bright light, including both literal radiance (like lightning or polished metal) and metaphorical brilliance (like splendor or magnificence).');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4953, 2458, 'Longing and Yearning', 1, 'This domain encompasses words expressing intense desire, yearning, or longing for something or someone, particularly emotional or spiritual longing.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4954, 2454, 'Physical Blindness', 1, 'This domain encompasses words describing the physical condition of being unable to see, whether applied to people, animals, or figuratively to lack of perception or understanding.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4955, 2451, 'Prisoners and Captives', 1, 'Words referring to people who are held in physical confinement, either as prisoners in jail or as captives taken in war or by force.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4956, 2453, 'Readiness and Preparation', 1, 'This domain encompasses states, processes, and qualities related to being ready, prepared, or in a state of preparedness for action, whether referring to physical readiness, mental willingness, or the act of making something ready.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4957, 2453, 'Divine and Human Authority', 1, 'Words referring to authority figures who exercise power or control over others, including the supreme divine Lord, human masters, owners, and rulers who have legitimate authority in various social contexts.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4958, 2443, 'Nakedness and Exposure', 1, 'Words describing the state of being without clothing or covering, ranging from complete nakedness to being poorly clothed or exposed, and extending metaphorically to destitution or lack of possessions.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4959, 2455, 'Worthless Agricultural Waste', 1, 'This domain encompasses terms for dry, lightweight agricultural byproducts like straw, stubble, and chaff that are easily destroyed by fire or wind and are often used metaphorically to represent worthlessness, weakness, or insignificance.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4960, 2456, 'Wages and Reward', 1, 'Words relating to payment or compensation given in exchange for labor, service, or faithful action, including monetary wages, hire-prices, and metaphorical rewards.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4961, 2454, 'Heap and Pile', 1, 'This domain contains words referring to physical accumulations or piles of materials, including stacks of grain sheaves, mounds of stones, heaps of ruins, piles of water, and other gathered masses.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4962, 2459, 'Sequential Order and Ranking', 1, 'This domain encompasses words denoting ordinal position, particularly "second" in sequences, hierarchies, or temporal repetitions, including second place in rank, second occurrence in time, and doubling.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4963, 2453, 'World Under Authority', 1, 'The inhabited world or universe viewed as a realm under divine sovereignty, judgment, or human governance, including its peoples and systems of order.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4964, 2444, 'Tenth Day Observances', 1, 'This domain encompasses words and phrases designating the tenth day of a month or the ordinal number tenth, particularly in contexts related to religious festivals, sacred calendars, and ritual observances requiring specific timing.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4965, 2454, 'Prophets and Prophecy', 1, 'People who speak on behalf of God or gods, interpreting and revealing divine will, foretelling future events, or delivering inspired messages.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4966, 2462, 'Fasting and Food Abstinence', 1, 'Words referring to the voluntary abstinence from food, either as a religious practice, spiritual discipline, or state of being without food.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4967, 2454, 'Egyptian Royal Title', 1, 'Words referring to Pharaoh, the title used for the kings of ancient Egypt throughout biblical history.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4968, 2446, 'Lying and Falsehood', 1, 'Words related to the act of lying, telling falsehoods, deceiving others through speech, or being proven false.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4969, 2445, 'Night and Overnight Stay', 1, 'Words related to the period of darkness between sunset and sunrise, and activities associated with spending time during this period, including lodging, remaining, or dwelling in a place overnight.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4970, 2444, 'Rock and Stone Formations', 1, 'Natural rock formations including cliffs, crags, boulders, and rocky terrain, as well as metaphorical uses of rock imagery for strength, permanence, and divine attributes.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4971, 2447, 'Flowering and Blossoming', 1, 'This domain encompasses words relating to the flowers, blossoms, and buds of plants, particularly grapevines, as well as clusters of fruit or flowers in their blooming state.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4972, 2445, 'Judgment and Justice', 1, 'This domain encompasses legal and judicial concepts including judging, adjudicating disputes, governing, vindicating the oppressed, condemning wrongdoers, and entering into legal controversies or trials.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4973, 2449, 'Doing Good and Beneficence', 1, 'This domain encompasses words and expressions related to performing good deeds, acting righteously, showing kindness to others, and being a benefactor.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4974, 2450, 'Truth and Measurement', 1, 'This domain encompasses concepts related to truth, faithfulness, reliability, and standards of measurement—all expressing the fundamental idea of correspondence to reality or an established standard.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4975, 2451, 'Locusts and Grasshoppers', 1, 'This domain contains words for various species of locusts and grasshoppers, typically depicted as destructive swarming insects, agents of divine judgment, or symbols of insignificance and multitude.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4976, 2443, 'Conspiracy and Plot', 1, 'This domain encompasses secret plans, schemes, and organized gatherings formed against others, including conspiracies, plots, seditious meetings, and treacherous intentions.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4977, 2443, 'Stewardship and Administration', 1, 'This domain encompasses roles and actions involving the management, oversight, and administration of households, estates, or resources on behalf of an owner or authority.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4978, 2446, 'Mercy and Sparing', 1, 'Words related to showing compassion, pity, or restraint by refraining from harming, destroying, or punishing someone or something.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4979, 2448, 'Physical Weakness and Illness', 1, 'This domain encompasses concepts related to physical debility, sickness, disease, suffering, and the loss of bodily strength or health.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4980, 2446, 'Numerical Hundreds', 1, 'This domain contains words and expressions referring to the number hundred and its multiples (two hundred, three hundred, etc.), including both cardinal numerals and military organizational units based on hundreds.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4981, 2454, 'Calendar Months and Festivals', 1, 'Words referring to months as units of time measurement, lunar cycles, calendar periods, and periodic religious observances (especially new moon festivals).');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4982, 2458, 'Birth and Reproduction', 1, 'This domain encompasses words and expressions related to the biological process of giving birth, begetting offspring, and bringing forth new life, whether literal (human and animal reproduction) or figurative (producing results or consequences).');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4983, 2444, 'Recognition and Authority', 1, 'Words relating to the act of recognizing, acknowledging, or showing regard toward someone or something, especially in contexts involving differential treatment, judgment, or the validation of identity and status.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4984, 2450, 'Mental Understanding and Insight', 1, 'This domain encompasses words relating to the cognitive faculties of comprehension, discernment, wisdom, and intellectual grasp of knowledge or meaning.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4985, 2456, 'Prayer and Entreaty', 1, 'Words expressing polite requests, prayers, supplications, or entreaties, typically used when addressing superiors or deity, conveying humility and seeking permission or favor.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4986, 2462, 'Hunting and Prey', 1, 'This domain encompasses words related to the activity of hunting, the animals or objects hunted (game, prey), and associated concepts like lying in wait or taking catch.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4987, 2445, 'Drink and Beverage', 1, 'Words relating to the act of drinking liquids, giving others something to drink, beverages themselves, and watering or irrigating land or living beings.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4988, 2454, 'Adultery and Unfaithfulness', 1, 'Words related to the act of adultery, including committing adultery, adulterers, and adulteresses, both in literal marital unfaithfulness and metaphorical unfaithfulness to God through idolatry.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4989, 2445, 'Response and Testimony', 1, 'Words for verbal responses to questions or situations, including answering, replying, testifying as a witness, and giving evidence for or against someone.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4990, 2458, 'Planting and Implanting', 1, 'This domain covers words related to the act of planting vegetation (trees, vines, gardens) in the ground, as well as metaphorical extensions to implanting, establishing, or fixing things in place (including abstract concepts, people, or structures).');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4991, 2451, 'Lack and Scarcity', 1, 'Words describing states of deficiency, want, need, or poverty, particularly the absence or insufficiency of necessary resources or provisions.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4992, 2448, 'Reminding and Remembering', 1, 'Words referring to the act of causing someone to remember something, recalling information to mind, or making mention of past events or knowledge.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4993, 2456, 'Intoxication and Drunkenness', 1, 'Words related to the state of being drunk or intoxicated from alcoholic beverages, including becoming drunk, being in a state of drunkenness, and causing others to become intoxicated.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4994, 2450, 'Safety and Security', 1, 'This domain encompasses words relating to states of being safe, unharmed, protected from danger, and living without threat or fear.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4995, 2448, 'Anxiety and Worry', 1, 'This domain encompasses words describing mental states of anxiety, concern, apprehension, and worry about future events or present circumstances.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4996, 2445, 'Young Unmarried Women', 1, 'Words referring to young women who are sexually mature but unmarried, including virgins and maidens.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4997, 2458, 'Sleep and Rest', 1, 'This domain contains words referring to the physical state of sleep, including falling asleep, being asleep, and various metaphorical extensions such as spiritual inattentiveness, death as sleep, and divine inactivity.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4998, 2443, 'Personal and Place Names', 1, 'Proper names referring to specific individuals and geographical locations, including variations of names like Sheba, Sheva, and related forms used to identify people and territories in biblical texts.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (4999, 2454, 'Bronze and Copper', 1, 'Words referring to copper or bronze as a metal, including objects made from these metals such as fetters, vessels, and armor, as well as figurative uses denoting strength or hardness.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5000, 2444, 'Jerusalem (Place Name)', 1, 'Various Greek and Hebrew forms and grammatical cases of the proper noun "Jerusalem," referring to the historical city as both a physical location and its inhabitants, including symbolic/heavenly references.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5001, 2446, 'Commerce and Betrayal', 1, 'This domain encompasses words related to selling goods or people in commercial transactions, including the extension to metaphorical meanings of betrayal, exploitation, or giving something up for a price.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5002, 2455, 'Theft and Stealing', 1, 'This domain encompasses words related to the act of taking someone else''s property without permission, including stealing objects, kidnapping people, and moving stealthily to avoid detection.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5003, 2454, 'Flesh and Meat', 1, 'This domain encompasses words referring to the physical substance of flesh, whether as the tissue of living bodies (human or animal), edible meat, or the body itself as a physical/mortal entity, including figurative extensions to kinship relations and human frailty.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5004, 2454, 'Divine Name YHWH', 1, 'This domain contains the various grammatical forms and contextual uses of the Tetragrammaton (YHWH/Yahweh), the proper personal name of the God of Israel, including its combinations with prepositions and its appearance in compound phrases.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5005, 2458, 'Preceding Movement', 1, 'Words describing motion or position that comes before something else in space, time, or sequence, including going ahead, leading the way, or arriving first.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5006, 2462, 'Quantity and Possession', 1, 'Words expressing the concept of having, possessing, holding, or containing something, including states of being, pregnancy, and numerical or spatial relationships.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5007, 2443, 'Mother and Queen-Mother', 1, 'This domain encompasses words referring to mothers (both human and animal), queen-mothers (mothers of kings who held positions of dignity and influence), and related maternal roles including metaphorical uses for cities, nations, and sources of things.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5008, 2444, 'Violent and Criminal Persons', 1, 'This domain includes words referring to people who commit violent crimes or acts of aggression, particularly robbers, bandits, pirates, and those who use force against others.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5009, 2455, 'Adding and Continuing', 1, 'This domain encompasses actions of placing something upon, joining to, or increasing something else, as well as repeating or continuing an action beyond its initial occurrence.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5010, 2446, 'Feast and Banquet', 1, 'This domain includes words referring to formal meals, celebrations, feasts, banquets, and the social gatherings centered around eating and drinking together.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5011, 2445, '** Verbal Reproach and Insult', 1, '** Words referring to acts of reproaching, taunting, reviling, or insulting someone through critical or hostile speech.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5012, 2460, 'Guilt and Legal Liability', 1, 'Words describing a person''s state of being guilty, liable, culpable, or subject to legal penalty or punishment for wrongdoing or offense.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5013, 2443, 'Measure and Estimate', 1, 'This domain encompasses words related to the act of measuring physical dimensions, quantities, or distances, as well as figuratively evaluating, estimating, or judging abstract concepts like character or worth.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5014, 2458, 'Hanging and Suspension', 1, 'This domain encompasses words related to objects or people being suspended, hung up, or in a hanging position, whether from natural causes, as decorative displays, or as a form of execution.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5015, 2454, 'Body Armor and Protection', 1, 'This domain contains words referring to defensive military equipment worn on the body, particularly various types of armor, breastplates, and protective garments used in warfare.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5016, 2452, 'Change and Transformation', 1, 'Events involving alteration, modification, or transformation of state, form, appearance, or nature, including exchanging one thing for another.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5017, 2457, 'Speaking and Verbal Communication', 1, 'This domain encompasses words and expressions related to the act of speaking, telling, uttering, or communicating verbally with others, including various modes of speech such as declaring, pronouncing, conversing, and announcing.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5018, 2458, 'Forceful Removal and Separation', 1, 'This domain encompasses actions involving pulling, tearing, plucking, or drawing something away from its original position or attachment, whether physically (like plucking grain, tearing hair, breaking bonds) or metaphorically (like being estranged or separated).');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5019, 2455, 'Generation and Lineage', 1, 'This domain encompasses concepts related to temporal succession of people, including generations, descendants, ancestry, family lines, and groups of contemporaries living at the same time.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5020, 2444, 'Stripping and Exposing', 1, 'This domain encompasses actions of removing clothing, coverings, or outer layers from people, objects, or surfaces, often resulting in nakedness, vulnerability, or exposure.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5021, 2454, 'Rivers and Streams', 1, 'Words referring to natural or artificial flowing bodies of water, including rivers, streams, canals, and watercourses.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5022, 2443, 'Light Sources and Illumination', 1, 'This domain encompasses physical light-producing objects such as lamps, torches, and lanterns, as well as their metaphorical uses to represent life, guidance, prosperity, or divine illumination.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5023, 2449, 'Past Time Reference', 1, 'Words referring to the recent or distant past, particularly temporal expressions that indicate times prior to the present moment, such as "yesterday," "formerly," or "long ago."');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5024, 2460, 'Curse and Malediction', 1, 'Words related to pronouncing curses, invoking divine judgment or harm upon someone or something, and the resulting state of being under a curse or divine condemnation.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5025, 2454, 'Dream Interpretation', 1, 'This domain contains words related to the supernatural interpretation or explanation of divine revelations, particularly dreams and visions that require spiritual insight to understand.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5026, 2454, 'Young Men and Boys', 1, 'Words referring to male individuals in the stages of youth, from infancy through young adulthood, including boys, lads, youths, and young men in their prime.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5027, 2443, 'Low Status Person', 1, 'Words describing persons of inferior rank, position, or social standing, including those who are last, lowest, or least important in a hierarchy or sequence.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5028, 2447, 'Oppression and Injustice', 1, 'Words referring to the cruel exercise of power or authority, including acts of oppression, extortion, and unjust treatment that exploit or harm others.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5029, 2445, 'Judge and Judgment Officials', 1, 'This domain includes words referring to people who hold the office or role of judging, deciding legal cases, resolving disputes, executing justice, or serving as magistrates and judicial authorities.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5030, 2446, 'Kinship and Brotherhood Terms', 1, 'Words referring to brothers and related familial, social, or spiritual relationships, including literal siblings, kinsmen, associates, and fellow members of religious communities.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5031, 2455, 'Urging to Eat', 1, 'Words describing the act of pressing, urging, or insisting that someone eat or drink, often in contexts of hospitality.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5032, 2459, 'Wonders and Marvels', 1, 'Words referring to extraordinary, supernatural, or miraculous events and acts that inspire awe and astonishment, particularly divine signs and portents that display God''s power.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5033, 2449, 'Foot and Movement', 1, 'This domain encompasses words related to the foot as a body part, its use in walking and running, foot-based measurement, and associated actions like trampling or pursuing.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5034, 2450, 'Left Side and Direction', 1, 'Words referring to the left side of the body, left hand, leftward direction, and by extension the north (based on facing east in ancient Near Eastern orientation).');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5035, 2451, 'Time of Discovery/Arrival', 1, 'Words describing the temporal aspect of finding, discovering, or coming upon something or someone, often unexpectedly or at a particular moment.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5036, 2444, 'Encircling and Surrounding', 1, 'This domain pertains to spatial arrangements where entities are positioned around, about, or encircling a central point or object, including physical placement in a circuit and the inhabitants or objects occupying surrounding areas.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5037, 2455, 'Worship and reverence', 1, 'Actions expressing religious devotion, reverence, or homage to God, deities, or authority figures through physical gestures like bowing down or prostrating oneself.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5038, 2443, 'Weapons and Armaments', 1, 'This domain encompasses words referring to physical instruments of warfare and combat, including missiles, projectiles, defensive armor, military equipment, and arsenals where such implements are stored.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5039, 2455, 'Curse and Revile', 1, 'Words referring to pronouncing curses, speaking evil against someone, or calling down harm upon a person through verbal utterances, as well as treating someone with contempt through abusive speech.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5040, 2444, 'Model or Example', 1, 'This domain contains words referring to patterns, models, types, or examples that serve as standards for imitation or comparison, whether physical representations (like impressions, molds, or images) or abstract standards (like exemplary behavior or prototypes).');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5041, 2456, 'Moral Obscurity and Depth', 1, 'This domain encompasses terms describing moral or spiritual darkness, inscrutability, and the unfathomable depths of wickedness, calamity, or hidden evil that are difficult to perceive or understand.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5042, 2458, 'Thanksgiving and Gratitude', 1, 'This domain encompasses expressions of thanks, praise, and gratitude, including verbal expressions of thanksgiving, liturgical acts of praise, ceremonial processions or choirs giving thanks, and sacrificial offerings made in gratitude.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5043, 2452, 'Salvation and Deliverance', 1, 'Words referring to being rescued, saved, or delivered from danger, oppression, or trouble, whether by human or divine intervention, including physical rescue, spiritual salvation, and military victory.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5044, 2443, 'Fellowship and Partnership', 1, 'Words referring to people who share in something together, particularly in religious life, spiritual benefits, or sacred community, including partners, companions, and co-participants in faith.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5045, 2454, 'Fish and Fishing', 1, 'This domain contains words referring to fish as creatures, whether individually or collectively, as well as activities related to catching fish.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5046, 2455, 'Total Consumption/Destruction', 1, 'Words describing the complete consumption, swallowing up, or total destruction of something, whether literally (physically swallowing or engulfing) or metaphorically (devastating, annihilating, or overwhelming completely).');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5047, 2454, 'Jewish Ethnic Identity', 1, 'Words referring to people, tribes, territories, and nations associated with Judah, including descendants of Jacob''s son Judah, members of the Jewish people, the kingdom and land of Judah, and specific individuals bearing the name Judah/Judas.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5048, 2454, 'Passover Festival and Sacrifice', 1, 'Words related to the Jewish Passover festival, including the festival itself, the sacrificial animal victim offered during Passover, and personal names derived from the Passover term.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5049, 2445, 'Endurance and Tolerance', 1, 'This domain encompasses words relating to bearing, enduring, putting up with, or tolerating difficult circumstances, burdens, behaviors, or people with patience and perseverance.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5050, 2454, 'City as Artifact', 1, 'This domain contains references to cities and settlements viewed as constructed human artifacts, particularly the ancient city of Hebron with its buildings, walls, and urban infrastructure.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5051, 2447, 'Mental Confusion and Perplexity', 1, 'This domain contains words describing states of mental bewilderment, uncertainty, or confusion where someone is puzzled, at a loss, or unable to understand or decide what to do.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5052, 2448, 'Heavy Burden Weight', 1, 'This domain encompasses concepts of physical heaviness, burdensome loads, severity, and abundance, extending metaphorically to include oppressive circumstances, difficulty, and large quantities.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5053, 2443, 'Worms and Insects', 1, 'Small invertebrate creatures, particularly those associated with decay, destruction of plants, or infestation, including various types of worms, maggots, moths, and locusts.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5054, 2450, 'Beloved and Dear Ones', 1, 'This domain encompasses terms describing people who are loved, cherished, or held dear, including beloved individuals, only children, and those who are objects of special affection.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5055, 2454, 'Moon and Lunar Cycles', 1, 'Words referring to the moon as a celestial body, often mentioned alongside the sun and stars, serving as a marker of time, seasons, and months.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5056, 2452, 'West/Western Direction', 1, 'This domain includes words and expressions that refer to the western cardinal direction, westward movement, or western location, often conceptualized through the setting sun or the Mediterranean Sea''s position relative to ancient Israel.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5057, 2454, 'Plague and Pestilence', 1, 'Words referring to infectious diseases, epidemics, and divine judgments manifested as widespread illness or death, often sent as punishment or calamity.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5058, 2454, 'Craft and Creation', 1, 'Words relating to the physical forming, shaping, and fashioning of objects, particularly by potters and artisans working with clay or other materials, extended metaphorically to divine creation and planning.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5059, 2454, 'Cloud and Sky Phenomena', 1, 'This domain encompasses words referring to clouds, cloud masses, and related atmospheric phenomena including rain clouds, mist, fog, and their metaphorical uses in religious and poetic contexts.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5060, 2456, 'Recompense and Retribution', 1, 'Words referring to repayment, requital, or reward given in response to someone''s actions, whether positive (benefit, reward) or negative (retribution, punishment).');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5061, 2443, 'Miscellaneous Terms', 1, 'A diverse collection of words including location markers, numbers, proper names, and various concrete nouns that don''t form a unified semantic category.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5062, 2458, 'Ritual and Moral Impurity', 1, 'This domain encompasses terms for ceremonial uncleanness, defilement, and pollution, including both physical filth and metaphorical moral corruption, particularly in religious and ethical contexts.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5063, 2454, 'Suffering and Affliction', 1, 'This domain encompasses experiences of physical, emotional, or social distress including suffering, affliction, oppression, misery, and tribulation that befall individuals or groups.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5064, 2448, 'Wool and Fibers', 1, 'This domain contains words referring to wool and similar textile fibers used in religious contexts, particularly in the making of sacred garments and offerings.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5065, 2461, 'Affliction and Tribulation', 1, 'This domain covers words describing physical pressure, compression, or constraint that metaphorically extend to spiritual, emotional, or circumstantial oppression, distress, and suffering, particularly in the context of persecution or hardship endured by believers.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5066, 2462, 'Spatial Separation and Distance', 1, 'This domain encompasses verbs and concepts describing physical movement away from a point of origin, the creation of spatial intervals or gaps, and the act of removing or displacing objects or people from their original positions.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5067, 2458, 'Mock and Ridicule', 1, 'Words describing actions of mocking, ridiculing, scorning, deriding, or jeering at others, typically expressing contempt or scorn through speech or laughter.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5068, 2444, 'Tongue and Language', 1, 'This domain encompasses words relating to the physical tongue as a body part and organ of speech, as well as extended meanings including spoken language, dialect, and the act of speaking or communicating.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5069, 2458, 'Abundance and Excess', 1, 'This domain encompasses words expressing the concepts of surplus, overflow, superabundance, having more than enough, remaining portions, and exceeding normal or expected quantities.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5070, 2450, 'Sobriety and Self-Control', 1, 'This domain encompasses words relating to being sober (not intoxicated), maintaining clear-mindedness, exercising self-control, and demonstrating temperance or moderation in behavior.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5071, 2447, 'Genuine and Authentic', 1, 'This domain contains words describing things or persons that are genuine, true, real, authentic, legitimate, or unadulterated, as opposed to false, counterfeit, adulterated, or merely apparent.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5072, 2458, 'Agreement and Consent', 1, 'This domain contains words related to agreeing with others, giving consent or approval, reaching harmony in opinion, and making bargains or agreements together.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5073, 2450, 'Purple Dye and Cloth', 1, 'This domain encompasses words related to purple coloring, including the purple dye extracted from shellfish, purple-dyed fabrics and garments, the color purple itself, and those who trade in purple goods.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5074, 2455, 'Jealousy and Zeal', 1, 'Words relating to intense emotional responses involving rivalry, envy, protective devotion, or passionate commitment toward persons, possessions, or causes.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5075, 2451, 'Opposition and Hostility', 1, 'This domain contains words expressing opposition, resistance, or adversarial relationships, including being set against, contradicting, or actively resisting someone or something.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5076, 2443, 'Sun-related Place Names', 1, 'Biblical place names that incorporate references to the sun (shemesh), including En-Shemesh, Ir-Shemesh, and Beth-Shemesh (sun temple), representing locations named after solar imagery or possibly associated with sun worship.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5077, 2454, 'Snow and precipitation', 1, 'Words referring to snow as a natural phenomenon, including its appearance, effects, and use in comparisons for whiteness, coldness, and purity.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5078, 2445, 'Oaths and Vows', 1, 'Words related to making solemn pledges, promises, or declarations, often invoking a deity or sacred object as witness or guarantee of truthfulness.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5079, 2446, 'Mental Reflection and Pondering', 1, 'This domain encompasses cognitive activities involving deep thought, contemplation, and internal processing of ideas, ranging from focused meditation on specific subjects to more general musing, pondering, and careful consideration.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5080, 2454, 'Heard/Heeded Names', 1, 'Personal names derived from Hebrew roots meaning "heard" or "heeded," primarily referring to Simeon/Shimon (son of Jacob whose name was explained as "the LORD has heard") and related namesakes.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5081, 2459, 'Humility and Lowliness', 1, 'This domain encompasses words describing humble attitudes, low social status, meekness, and modest behavior, whether as physical lowness, social position, or moral virtue of self-abasement before God or others.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5082, 2444, 'Ovens and Furnaces', 1, 'This domain includes words for heated chambers used for cooking, baking, smelting metals, or as instruments of punishment and judgment, whether used literally or figuratively.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5083, 2459, 'Laziness and Sloth', 1, 'This domain encompasses words describing the state or quality of being inactive, sluggish, or unwilling to work or expend effort, including both the character trait of laziness and the act of being idle.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5084, 2450, 'Confidence and Boldness', 1, 'This domain encompasses terms expressing courage, confidence, boldness, and assurance in speech or action, particularly the confidence to approach God or speak freely in religious contexts.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5085, 2455, 'Body Parts: Loins', 1, 'Physical body parts referring to the loins, waist, or lower back region, often associated with strength, virility, or the place where garments and weapons are secured.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5086, 2454, 'Dust and Fine Particles', 1, 'This domain contains words referring to dust, powder, fine particles, and related substances including dry earth, soil, debris, and airborne particulate matter.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5087, 2443, 'Medes and Media', 1, 'Words referring to the Medes as a people group and Media as their geographical territory, an ancient empire located in what is now northwestern Iran.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5088, 2444, 'Geographic Regions and Places', 1, 'This domain contains proper names of regions, territories, and lands, particularly referring to Aram (Syria/Mesopotamia) and its subdivisions like Paddan-Aram.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5089, 2454, 'Jacob/James Names', 1, 'Personal names derived from the Hebrew name Jacob (Ya''aqob), including the patriarch Jacob, his descendants as a nation, and the Greek form James (Iakobos) used for various New Testament figures.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5090, 2454, 'Neck and Throat', 1, 'Words referring to the neck and throat as body parts, including actions performed on them (such as breaking the neck of an animal) and metaphorical uses (such as stiff-necked stubbornness).');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5091, 2455, 'Construction and Building', 1, 'This domain encompasses actions related to physical construction (building structures like houses, temples, walls, altars) as well as metaphorical building (establishing families, communities, or providing spiritual edification).');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5092, 2461, 'Traps and Snares', 1, 'Devices used to catch animals or birds, and metaphorically extended to refer to entrapment, plots, dangers, or anything that ensnares or entraps people.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5093, 2454, 'Isaac Proper Name', 1, 'This domain contains references to Isaac, the son of Abraham and Sarah, as a proper name in various grammatical forms and contexts throughout the biblical text.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5094, 2443, 'Personal Names - Joram/Jehoram', 1, 'This domain contains various forms and grammatical variations of the Hebrew personal names Joram and Jehoram (meaning "Yahweh is exalted"), referring to several biblical figures including kings of Judah and Israel, a priest, and a Levite.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5095, 2454, 'Personal Names: Joseph', 1, 'Proper names referring to individuals named Joseph across biblical history, including Jacob''s son, ancestors of Jesus, and various other biblical figures bearing this name.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5096, 2446, 'Physical Instability and Shaking', 1, 'Events involving loss of balance, wavering motion, or unstable movement, whether of physical objects (mountains, buildings, body parts) or metaphorical entities (people''s security, faith, social position).');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5097, 2453, 'Counsel and Planning', 1, 'This domain encompasses actions related to giving advice, consulting together, deliberating, and forming plans or strategies, whether individually or in groups.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5098, 2454, 'Tribal Names and Identities', 1, 'This domain contains proper names and gentilics (ethnic identifiers) related to Benjamin, one of the twelve tribes of Israel, including the name of the patriarch, the tribal designation, and terms for members of the tribe.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5099, 2457, 'Israelite Tribe Dan', 1, 'Words referring to Dan as a person (son of Jacob), the tribe descended from him, the territory or city named after the tribe, and the people belonging to this tribe.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5100, 2459, 'Hail and Hailstorms', 1, 'This domain contains words referring to hail as frozen precipitation that falls from the sky, often associated with divine judgment or natural disasters in biblical texts.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5101, 2455, 'Plant Growth and Sprouting', 1, 'This domain encompasses words describing the natural processes of plants growing, sprouting, budding, and producing shoots or offspring, including both literal botanical growth and metaphorical extensions to human birth and development.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5102, 2459, 'Friend and Companion', 1, 'Words referring to close personal relationships characterized by mutual affection, companionship, and social bonding, including friends, companions, associates, and intimate acquaintances.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5103, 2459, 'Alternative and Differentiation', 1, 'This domain encompasses words expressing alternatives, distinctions, and contrasts, including "other," "another," "different," and "next" in temporal or sequential contexts, often used to distinguish between two or more entities or to indicate something beyond what has already been mentioned.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5104, 2460, 'Aaronic Priesthood', 1, 'This domain contains references to Aaron, the first high priest of Israel, his descendants, and the priestly lineage established through him for conducting worship and temple service.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5105, 2461, 'Ritual Flour Offerings', 1, 'Fine flour and meal used in sacred offerings, religious ceremonies, and as provisions for priests in worship contexts.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5106, 2462, 'Aromatic Spices and Incense', 1, 'This domain contains words referring to fragrant spices, perfumes, and aromatic substances used in worship rituals, burial practices, commerce, and personal adornment.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5107, 2443, 'Need and Necessity', 1, 'Words relating to lack, want, requirement, or compulsion that drives a person to seek something or act in a particular way.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5108, 2444, 'Physical Stability and Firmness', 1, 'This domain encompasses concepts related to physical and metaphorical stability, firmness, establishment, and steadfastness, including being fixed in place, solidly supported, or enduringly established.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5109, 2448, 'Temporal Reference: Then', 1, 'Words that refer to a point in time, either past or future, often in relation to other events or as a consequence of a condition, typically translated as "then," "at that time," or "since."');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5110, 2446, 'Venomous Serpents and Snakes', 1, 'This domain encompasses various types of snakes and serpents, including venomous species like vipers, cobras, and asps, as well as mythological serpent creatures and dragons mentioned in biblical texts.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5111, 2454, 'Legal Punishment and Penalty', 1, 'This domain encompasses terms related to judicial penalties, divine retribution, legal consequences, and punitive measures imposed as a result of wrongdoing or transgression.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5112, 2448, 'Transfer of Control', 1, 'Words describing the action of handing over, delivering, or transferring a person, object, or responsibility from one party to another, including custody, betrayal, tradition, and entrusting.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5113, 2449, 'Silence and Stillness', 1, 'This domain encompasses words describing the absence of sound, speech, or movement, including calm, quiet, rest, and the act of keeping silent or being unable to speak.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5114, 2460, 'Burial and Interment', 1, 'Words and expressions related to the act of burying the dead, including preparing bodies for burial, performing burial rites, and the role of those who bury.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5115, 2451, 'Freedom and Liberty', 1, 'Words relating to freedom from slavery, bondage, obligations, or oppression, including legal release, manumission, and proclamation of liberty.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5116, 2458, 'Wind and Breath Events', 1, 'Events involving the movement of air, including wind blowing, breathing (both literal respiration and metaphorical utterance), and actions that involve air flow such as kindling flames or emitting odors.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5117, 2456, 'Care and Concern', 1, 'Words describing the act of caring about, being concerned with, or taking responsibility for something or someone, including both emotional investment and active attention or management.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5118, 2444, 'Remainder and Continuation', 1, 'This domain encompasses words that express what is left over, remaining, or continuing after something else has been removed, completed, or discussed, including temporal expressions about future time and discourse markers for transitioning to final points.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5119, 2455, 'Compulsion and Force', 1, 'This domain encompasses words describing actions of forcing, compelling, or constraining someone to do something against their will or through the application of pressure, whether physical, social, or argumentative.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5120, 2444, 'Knowledge and Understanding', 1, 'This domain encompasses verbs expressing cognitive states of knowing, understanding, recognizing, and being skilled or acquainted with information, people, or abilities.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5121, 2457, 'Teaching and Instruction', 1, 'This domain encompasses words related to the act of teaching, the content taught (doctrine, instruction), and the learning or knowledge received through formal or persuasive instruction.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5122, 2456, 'Vengeance and Retribution', 1, 'Words relating to acts of avenging wrongs, punishing offenses, or seeking satisfaction for injuries, whether carried out by God, individuals, or nations in response to wrongdoing.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5123, 2454, 'Hired Workers and Laborers', 1, 'This domain encompasses words referring to people who work for wages or payment, including general workers, day laborers, hired servants, and mercenaries who receive compensation for their labor or services.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5124, 2445, 'Fourth in sequence', 1, 'Words referring to the ordinal number fourth, indicating position in a series or sequence, including related concepts like fourth generation, fourth part/quarter, and square (four-sided) shapes.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5125, 2461, 'Divine Scrutiny and Investigation', 1, 'This domain encompasses words related to searching, examining, and investigating with careful attention, particularly in contexts involving the discovery or discernment of divine truth, spiritual matters, or sacred knowledge.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5126, 2445, 'Break/Violate Covenant or Promise', 1, 'Words relating to the breaking, violating, or annulling of covenants, agreements, vows, or promises, including both literal breaking of objects and metaphorical breaking of commitments.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5127, 2443, 'Ritual Purification Process', 1, 'Words referring to the ceremonial or ritual acts and processes of cleansing and purification, especially in religious contexts such as cleansing from physical impurity, disease, or contact with death.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5128, 2444, 'Synagogue and Assembly', 1, 'Words relating to Jewish places of worship, religious assemblies, gatherings of people, and those who lead or are associated with synagogues.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5129, 2456, 'Ammonite ethnic designation', 1, 'Words referring to people from Ammon, including ethnic labels, demonyms, and gentilic adjectives that identify individuals or groups as belonging to the Ammonite nation or territory.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5130, 2446, 'Sounds of Distress', 1, 'Vocal expressions of physical or emotional pain, suffering, or grief, including sighing, groaning, and moaning.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5131, 2458, 'Legal Accusation and Prosecution', 1, 'Words referring to formally accusing someone of wrongdoing, bringing charges against them in a legal context, or being the subject of such accusations.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5132, 2461, 'Testing and Proving', 1, 'Words referring to examining, testing, or proving the quality, character, or faithfulness of people or things, including divine testing of humans and human testing of God.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5133, 2458, 'Flying and Rapid Movement', 1, 'This domain encompasses terms related to flying, soaring, darting, and swift movement through the air, typically describing birds, arrows, celestial beings, or metaphorical rapid motion and fleeting phenomena.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5134, 2452, 'Alcoholic Beverages', 1, 'This domain contains words referring to fermented or intoxicating drinks, particularly strong alcoholic beverages other than wine, including beer and other spirits used for consumption or ritual purposes.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5135, 2454, 'Body Parts - Lower Limbs', 1, 'This domain contains terms referring to the lower extremities of humans and animals, including feet, legs, thighs, and their parts from the hip down to the toes.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5136, 2452, 'Sinful People', 1, 'This domain contains words that describe people who commit sins or transgressions against God or moral law, either as a descriptive attribute or as a substantive label for such individuals.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5137, 2443, 'Personal Names - Uzziah', 1, 'Proper names referring to various individuals named Uzziah (meaning "my strength is Yahweh"), most notably the king of Judah, but also including other biblical figures such as a hero of David, a Levite, a priest, and persons from the tribe of Judah.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5138, 2443, 'Building and Construction', 1, 'This domain contains words referring to physical structures, buildings, and architectural constructions, including both the process of building up and the completed edifices.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5139, 2454, 'Nobility and High Status', 1, 'This domain encompasses words referring to people of high social rank, birth, or character, including nobles, princes, and those distinguished by either hereditary status or noble-minded qualities.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5140, 2456, 'Singing and Musical Praise', 1, 'This domain encompasses words related to singing, chanting, and making music, particularly in contexts of worship, celebration, and emotional expression through vocal or instrumental performance.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5141, 2444, 'Philistine City Ashdod', 1, 'This domain contains references to Ashdod (also called Azotus in Greek), one of the five major Philistine cities located on the Mediterranean coast west of Jerusalem, frequently mentioned in contexts of conflict, judgment, and territorial boundaries.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5142, 2451, 'Fruit Ripeness States', 1, 'Words referring to grapes and figs in various stages of ripeness, from unripe or sour fruit to fully mature fruit ready for consumption or processing.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5143, 2459, 'Demonic Possession and Spirits', 1, 'This domain encompasses words related to demons, evil spirits, and the state of being possessed or controlled by such supernatural malevolent beings.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5144, 2454, 'Oaths and Vows', 1, 'This domain encompasses solemn verbal commitments made before God or witnesses, including sworn promises, covenantal oaths, curses invoked as guarantees, and the act of binding oneself or others through such declarations.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5145, 2458, 'Textual Variants and Scribal Readings', 1, 'This domain contains word senses that represent textual variants, scribal notes, and alternative readings (Ketiv/Qere) found in Biblical manuscripts, rather than words with unified semantic content.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5146, 2452, 'Song and Musical Composition', 1, 'This domain encompasses words referring to songs, melodies, odes, and musical compositions, including both secular songs (love songs, joyful songs, triumphal songs) and religious songs of worship and praise.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5147, 2443, 'Egypt and Egyptians', 1, 'Words referring to Egypt as a geographic location, political entity, or people group, including the land of Egypt, the Egyptian nation/kingdom, and Egyptian people.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5148, 2459, 'Number Three', 1, 'Words and expressions referring to the cardinal number three, including numerical quantifiers, ordinal uses, and related groupings or divisions into thirds.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5149, 2445, 'Blood and Bloodshed', 1, 'This domain encompasses terms related to blood as a physical substance, the shedding of blood through violence or murder, and the guilt or liability associated with bloodshed.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5150, 2454, 'Military Forces and Armies', 1, 'This domain encompasses organized military groups, including armies, troops, legions, camps, and hosts used for warfare or service, as well as figurative extensions to celestial beings and divine titles.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5151, 2451, 'Similarity and Equivalence', 1, 'This domain contains adverbs and expressions indicating similarity, equivalence, or parallelism between actions, states, or things, particularly the concept of "likewise" or "in the same manner."');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5152, 2460, 'Personal Names: Shimei', 1, 'Proper names referring to various individuals named Shimei (or variant spellings) and their descendants mentioned in biblical texts, spanning different tribes and time periods.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5153, 2454, 'Barley Grain', 1, 'Words referring to barley, a cereal grain crop grown for food and animal fodder, including the standing crop, harvested grains, and products made from barley.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5154, 2445, 'Terrifying and Horrible Things', 1, 'This domain contains words describing things, people, or situations that inspire fear, terror, awe, or horror through their threatening, formidable, or dreadful nature.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5155, 2450, 'Wisdom and Discernment', 1, 'This domain encompasses terms related to wisdom, understanding, and practical insight, including technical skill, administrative ability, shrewdness, and both divine and human knowledge—ranging from craftsmanship to ethical and religious understanding.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5156, 2455, 'Weighing and Measuring', 1, 'Events involving the physical act of weighing objects (especially metals for payment) or the figurative evaluation and assessment of worth, character, or actions.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5157, 2455, 'Palm Tree Representation', 1, 'Words referring to palm trees, palm tree imagery, and representations of palm trees whether as living plants, decorative figures, or symbolic objects.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5158, 2454, 'Healing and Restoration', 1, 'This domain encompasses words and expressions related to physical, spiritual, or metaphorical healing, curing diseases, treating wounds, and restoring wholeness or health.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5159, 2459, 'Error and Straying', 1, 'Words describing deviating from a correct path, either physically (wandering, roaming), mentally (making mistakes, being confused), or morally/spiritually (going astray from God''s commands, being led into error or idolatry).');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5160, 2454, 'Slander and Malicious Speech', 1, 'This domain encompasses words related to speaking maliciously about others, including slander, accusation, gossip, and reviling, as well as references to the Devil as the archetypal accuser and slanderer.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5161, 2454, 'Profane Person Example', 1, 'This domain contains references to Esau as a Biblical figure used to exemplify moral or spiritual failure, particularly his selling of his birthright and being called profane in Hebrews 12:16.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5162, 2444, 'Windows and Openings', 1, 'Physical openings in walls, roofs, or structures that allow light, air, or visibility, including windows, lattices, sluices, and similar architectural features.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5163, 2445, 'Persistent Service and Devotion', 1, 'This domain encompasses words describing steadfast commitment, faithful service, and persevering dedication to a person, task, or calling, particularly in contexts of duty, ministry, or attendance.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5164, 2444, 'Sacred High Places', 1, 'Places of worship, particularly elevated locations or shrines used for religious activities, including both legitimate and illicit worship sites.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5165, 2461, 'Murderers and Killers', 1, 'This domain includes words referring to people who unlawfully kill other human beings, whether with premeditation (murderers, assassins) or without intent (manslayers).');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5166, 2443, 'Extraordinary and Wonderful', 1, 'This domain contains words describing things that are amazing, marvelous, extraordinary, or wonderful—often beyond normal human understanding or ability, particularly in reference to God''s miraculous acts.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5167, 2458, 'Mixed or Combined Substances', 1, 'This domain contains words referring to mixtures of different materials, species, or groups, including mixed fabrics, mixed populations of people, blended wines, and combined substances, often with connotations of prohibited or unusual combinations.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5168, 2450, 'Mental Observation and Consideration', 1, 'This domain encompasses words related to the cognitive acts of carefully observing, perceiving, contemplating, considering, and making judgments about something through mental attention and deliberation.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5169, 2450, 'Negation and Nonexistence', 1, 'This domain contains words expressing absence, negation, or nonexistence of people, things, or quantities, including pronouns and adjectives meaning "nothing," "no one," "none," or "not any."');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5170, 2454, 'Timber and Construction Wood', 1, 'This domain encompasses noble trees (cypress/fir) valued specifically as building materials for construction, shipbuilding, and decorative woodwork in temples and other structures.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5171, 2447, 'Weakness and Sickness', 1, 'This domain covers states of physical weakness, illness, disease, and related conditions that affect the body''s strength and health.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5172, 2443, 'Tombs and Graves', 1, 'Physical structures or places where the dead are buried, including monuments, sepulchers, and burial sites that serve as memorials for the deceased.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5173, 2454, 'Moses (Biblical Figure)', 1, 'References to Moses, the Hebrew prophet and lawgiver who led the Israelites out of Egypt and received the Torah, including references to his law and writings.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5174, 2459, 'Lameness and Limping', 1, 'This domain contains words describing physical impairment in walking or movement, specifically referring to people or animals who are lame, crippled, or who limp due to injury or disability affecting the legs or feet.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5175, 2443, 'Haran Place References', 1, 'This domain contains references to the city of Haran in northern Mesopotamia and the personal name Haran, including various prepositional forms indicating location, direction, and origin in relation to this place.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5176, 2444, 'Israel as Political Entity', 1, 'Words referring to Israel as a nation, kingdom, or political/ethnic entity, including references to the Northern Kingdom, Southern Kingdom (Judah), the united monarchy, or the people collectively in their national identity.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5177, 2443, 'Expulsion and Exile', 1, 'Words relating to being driven out, expelled, or living as a stranger in a foreign land, as reflected in the name Gershom which is explained as deriving from the Hebrew root meaning "to sojourn" or "to be a stranger there."');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5178, 2454, 'Bear (Animal)', 1, 'Words referring to bears as wild animals, including references to bears in various contexts such as dangerous encounters, female bears with cubs, and metaphorical uses.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5179, 2455, 'Water and Hydration', 1, 'This domain encompasses words related to water as a physical substance, including its various forms (rain, rivers, seas, springs), uses (drinking, washing, cooking), and associated concepts (watering places, waterless conditions).');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5180, 2456, 'Pleasing and Satisfaction', 1, 'Words relating to causing pleasure, satisfaction, or approval in another person, or experiencing such feelings oneself.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5181, 2443, 'Chaldean People and Territory', 1, 'This domain encompasses terms referring to the Chaldeans as an ethnic group, their geographical territory of Chaldea, and their association with specialized knowledge such as astrology and interpretation.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5182, 2454, 'Ethnic Groups and Regions', 1, 'This domain encompasses proper names of ethnic groups, peoples, nations, territories, and geographical regions, particularly those referring to Cush/Ethiopia and related peoples in the ancient Near East.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5183, 2458, 'Ritual Sprinkling and Scattering', 1, 'Words describing the ceremonial or deliberate act of throwing, sprinkling, dashing, or scattering substances (especially blood, water, oil, or other materials) in religious rituals or formal contexts, typically performed by authorized persons in sacred settings.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5184, 2445, 'Glorification and Honor', 1, 'This domain encompasses words related to giving glory, honor, or praise to God or others, including beautifying, magnifying, exalting, and the reflexive acts of being glorified or glorifying oneself.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5185, 2454, 'Mount of Olives Location', 1, 'Words referring to olive trees, olives, and the Mount of Olives as a sacred or significant location in biblical geography.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5186, 2462, 'Abraham Proper Name', 1, 'This domain contains the proper name Abraham (and its variant Abram), referring to the biblical patriarch whose name means "father of a multitude" or "exalted father."');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5187, 2449, 'Enslavement and Subjugation', 1, 'This domain encompasses words related to the act of enslaving, subjugating, or reducing someone to a state of bondage, whether literal slavery or metaphorical subjugation.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5188, 2444, 'Temporal Sequence', 1, 'Words indicating time relationships expressing when events occur in sequence, particularly those meaning "then," "afterward," "later," or "subsequently."');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5189, 2453, 'Satiety and Abundance', 1, 'This domain contains words referring to the state of being fully satisfied or filled, especially with food, or having an abundance that meets or exceeds one''s needs or desires.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5190, 2458, 'Belts and Girding', 1, 'This domain encompasses belts, girdles, sashes, and the actions of fastening them around the body, including both literal wearing of belts (for clothing, weapons, or tools) and figurative uses (being equipped with strength, righteousness, or prepared for action).');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5191, 2454, 'Faithfulness and Belief', 1, 'This domain encompasses terms related to trustworthiness, loyalty, reliability, and faith, both as attributes of persons (human or divine) and as dispositions of trust and belief toward others or God.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5192, 2448, 'Counting and Numbering', 1, 'This domain encompasses verbs related to counting, numbering, enumerating, reckoning, and calculating quantities of things, particularly animals, people, or objects.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5193, 2449, 'Emotional Disturbance and Agitation', 1, 'Words describing the causing or experiencing of mental, emotional, or physical disturbance, including being troubled, confused, stirred up, or thrown into disorder.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5194, 2454, 'Rebellion and Defiance', 1, 'Words describing acts of rebellion, disobedience, or defiance against authority, including political revolt against rulers and spiritual transgression against divine commands.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5195, 2444, 'Dreams and Visions', 1, 'Words referring to dreams, nocturnal visions, and things seen during sleep, including both ordinary dreams and prophetic revelations received while sleeping.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5196, 2443, 'Skin Diseases and Sores', 1, 'Words referring to painful skin conditions, including boils, ulcers, festering wounds, and eruptions that affect humans and animals.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5197, 2453, 'Ritual Sanctification Actions', 1, 'Actions related to making something or someone holy, consecrated, or set apart for sacred purposes, including dedicating objects and places, purifying people and things for worship, and treating God''s name as holy.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5198, 2461, 'Teachers and Guides', 1, 'Words referring to people who instruct, teach, lead, or guide others in knowledge, skills, or direction.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5199, 2455, 'Following and Continuation', 1, 'This domain encompasses concepts of following physically or mentally, pursuing a course of action, accompanying others, adhering to teachings or principles, and bringing matters to completion or fulfillment.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5200, 2451, 'Quenching and Extinguishing', 1, 'This domain encompasses verbs related to the literal and metaphorical extinguishing, quenching, or elimination of fire, light, emotions (especially anger/wrath), life, hope, or other intense states, including wiping out or canceling something completely.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5201, 2457, 'Resurrection and Awakening', 1, 'This domain encompasses words related to raising someone from death, sleep, or inactivity, including both physical resurrection and metaphorical awakening or stirring to action.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5202, 2444, 'Old Age and Aging', 1, 'This domain encompasses words and expressions referring to the state or period of being old, advanced in years, hoary-headedness, and the biological process of aging in human life.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5203, 2458, 'Prayer and Supplication', 1, 'Words relating to the act of praying, making requests, expressing wishes, or interceding with God or divine beings on behalf of oneself or others.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5204, 2444, 'Seventh Day Observance', 1, 'Words related to the ordinal number "seventh," particularly in religious contexts referring to the seventh day (Sabbath), seventh month, seventh year, and other ritual time periods that hold special significance in worship and religious law.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5205, 2453, 'Witness and Testimony', 1, 'Words related to bearing witness, giving testimony, or serving as evidence in legal, social, or religious contexts, including both persons who testify and the testimony itself.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5206, 2456, 'Naming and Designation', 1, 'Words related to the act of giving names to people or things, calling someone by a particular name, or designating and identifying entities through naming.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5207, 2453, 'Testimony and Witness', 1, 'Words referring to testimony, evidence, or witness-bearing in legal or religious contexts, including covenant documents and false witness.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5208, 2444, 'Vigilance and Watchfulness', 1, 'This domain encompasses words related to staying awake, being alert, keeping watch, and maintaining vigilance, whether literally (remaining physically awake) or figuratively (spiritual alertness and guarding).');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5209, 2445, 'Testimony and Warning', 1, 'This domain encompasses words related to bearing witness, giving testimony, and issuing warnings or admonitions, particularly in legal, prophetic, or solemn contexts.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5210, 2458, 'Spitting Actions', 1, 'This domain includes words and expressions related to the physical act of spitting or expectorating, particularly when done upon someone as a gesture of contempt, disrespect, or ritual significance.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5211, 2447, 'Sailing and Sea Travel', 1, 'Words referring to traveling by boat or ship on water, including sailing away, sailing to shore, and general navigation.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5212, 2454, 'Drunkards and Intoxication', 1, 'This domain contains words referring to people who are drunk or habitually consume excessive alcohol, including adjectives and nouns describing drunkenness and wine-bibbers.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5213, 2455, 'Chaff and Stubble', 1, 'Agricultural waste products consisting of the dry, lightweight husks and stems left over after grain threshing, typically used in similes depicting worthlessness or things easily blown away or burned.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5214, 2443, 'Personal Names - Hezekiah', 1, 'This domain contains various forms and grammatical cases of the proper name Hezekiah (meaning "Yahweh has strengthened"), referring to the King of Judah and other individuals bearing this name in the Hebrew Bible and New Testament.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5215, 2451, 'Scripture and Written Documents', 1, 'Words referring to sacred writings, particularly the Holy Scriptures, and other written or inscribed texts.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5216, 2452, 'Praise and Commendation', 1, 'Words referring to expressing approval, admiration, or honor toward someone (especially God), including acts of praising, songs of praise, and the resulting renown or fame.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5217, 2443, 'Ordinal Number Six', 1, 'This domain contains ordinal number terms indicating the sixth position in a sequence, such as "sixth day," "sixth month," or "sixth year."');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5218, 2443, 'Personal Names in Text', 1, 'This domain contains proper names of individuals (specifically variations of the name Azariah/Azaryahu) as they appear in biblical narrative and genealogical records.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5219, 2455, 'Trees and Woody Plants', 1, 'This domain encompasses living trees, woody plants, and vegetation, including specific types like tamarisks and broom-trees, as well as collective references to forest and cultivated trees.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5220, 2460, 'Life and Living', 1, 'This domain encompasses concepts related to being alive, continuing in life, reviving from death or illness, and the preservation of life, including both physical existence and vitality in the presence of God.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5221, 2454, 'Donkeys and Pack Animals', 1, 'This domain contains words referring to donkeys (both male and female), young donkeys, and beasts of burden used for riding, carrying loads, and agricultural work.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5222, 2446, 'Venomous Snakes', 1, 'Words referring to poisonous serpents and vipers, including specific types like cobras, asps, and horned snakes, typically used in poetic or figurative contexts to represent danger or evil.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5223, 2443, 'Signal Instruments', 1, 'Musical instruments, particularly horns and trumpets, used to signal, announce, gather people, sound alarms in warfare, or mark religious ceremonies and proclamations of authority.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5224, 2460, 'Innocence and Acquittal', 1, 'This domain encompasses terms related to being free from guilt, blame, or punishment, including legal and moral innocence, exemption from obligation or consequences, and the act of declaring someone guiltless or leaving them unpunished.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5225, 2454, 'Divine Provision Sweetness', 1, 'Words referring to honey and sweet substances that symbolize God''s blessing, provision, and abundance in the Promised Land, as well as the sweetness of divine teaching and wisdom.');
INSERT INTO domain_chirho (domain_id_chirho, parent_id_chirho, name_chirho, level_chirho, description_chirho) VALUES (5226, 2455, 'Loss of Children', 1, 'Words describing the state of being deprived of offspring through death, miscarriage, or barrenness, including both the condition of childlessness and the actions that cause it.');
